SELECT * FROM jsonb_to_recordset('[{"level":"SSS1","term":2,"seq":1,"name":"Prose Narrators and Point of View","slug":"lit-sss1-t2-prose-narrators-and-point-of-view","code":"G26LITSSS1T2U1","body":"# Prose Narrators and Point of View — SSS1 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nEvery story arrives through a speaking position. A narrator might participate in events or describe them from outside. Separate what a voice witnesses from what the reader can independently infer; an account is not automatically the author''s personal testimony.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> I watched the bus pull away while Efe remained at the kiosk. She waved to the driver, but I could not tell whether she had meant to board. At school I told everyone she was late; only later did I learn that she had been helping the elderly shopkeeper close his stall.\n\n## A worked close reading\nThe first-person speaker supplies incomplete knowledge. The later revelation challenges the earlier judgement of Efe. Cite ''could not tell'' as an explicit limit, and contrast the later account before arguing that the narrator''s understanding changes.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. First-person viewpoint\n**Meaning:** A narrator uses I or we to tell events within a particular range of knowledge.\n**In practice:** I watched the bus leave and could not explain Efe''s choice. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Third-person limited\n**Meaning:** An outside narrator follows one character''s perceptions rather than knowing everyone.\n**In practice:** She heard the locked door and wondered what her brother knew. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Omniscient perspective\n**Meaning:** A narrative voice can disclose information from several characters'' minds.\n**In practice:** Both traders privately feared that the storm would return. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Unreliable narration\n**Meaning:** A narrator''s account is limited or distorted in ways readers should question.\n**In practice:** I accused Efe of carelessness before learning why she stayed behind. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Narrative distance\n**Meaning:** The degree of closeness between the telling voice and events or emotions.\n**In practice:** Years later, the narrator describes the same quarrel with detachment. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["First-person viewpoint: A narrator uses I or we to tell events within a particular range of knowledge","Third-person limited: An outside narrator follows one character''s perceptions rather than knowing everyone","Omniscient perspective: A narrative voice can disclose information from several characters'' minds","Unreliable narration: A narrator''s account is limited or distorted in ways readers should question","Narrative distance: The degree of closeness between the telling voice and events or emotions"],"cards":[{"front":"What does \"First-person viewpoint\" mean in literary study?","back":"A narrator uses I or we to tell events within a particular range of knowledge. Example: I watched the bus leave and could not explain Efe''s choice.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Third-person limited\" mean in literary study?","back":"An outside narrator follows one character''s perceptions rather than knowing everyone. Example: She heard the locked door and wondered what her brother knew.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Omniscient perspective\" mean in literary study?","back":"A narrative voice can disclose information from several characters'' minds. Example: Both traders privately feared that the storm would return.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Unreliable narration\" mean in literary study?","back":"A narrator''s account is limited or distorted in ways readers should question. Example: I accused Efe of carelessness before learning why she stayed behind.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Narrative distance\" mean in literary study?","back":"The degree of closeness between the telling voice and events or emotions. Example: Years later, the narrator describes the same quarrel with detachment.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate prose narrators and point of view?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Prose Narrators and Point of View\", which literary concept matches this definition: A narrator uses I or we to tell events within a particular range of knowledge?","options":[{"id":"A","text":"Third-person limited"},{"id":"B","text":"First-person viewpoint"},{"id":"C","text":"Omniscient perspective"},{"id":"D","text":"Unreliable narration"}],"answer":"B","explanation":"First-person viewpoint is the correct concept because A narrator uses I or we to tell events within a particular range of knowledge. The model example is: I watched the bus leave and could not explain Efe''s choice. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Prose Narrators and Point of View\": I watched the bus leave and could not explain Efe''s choice?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Third-person limited"},{"id":"C","text":"Omniscient perspective"},{"id":"D","text":"Unreliable narration"}],"answer":"A","explanation":"The example illustrates First-person viewpoint: A narrator uses I or we to tell events within a particular range of knowledge. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Prose Narrators and Point of View\", which literary concept matches this definition: An outside narrator follows one character''s perceptions rather than knowing everyone?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Omniscient perspective"},{"id":"C","text":"Unreliable narration"},{"id":"D","text":"Third-person limited"}],"answer":"D","explanation":"Third-person limited is the correct concept because An outside narrator follows one character''s perceptions rather than knowing everyone. The model example is: She heard the locked door and wondered what her brother knew. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Prose Narrators and Point of View\": She heard the locked door and wondered what her brother knew?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Omniscient perspective"},{"id":"C","text":"Third-person limited"},{"id":"D","text":"Unreliable narration"}],"answer":"C","explanation":"The example illustrates Third-person limited: An outside narrator follows one character''s perceptions rather than knowing everyone. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Prose Narrators and Point of View\", which literary concept matches this definition: A narrative voice can disclose information from several characters'' minds?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Omniscient perspective"},{"id":"C","text":"Third-person limited"},{"id":"D","text":"Unreliable narration"}],"answer":"B","explanation":"Omniscient perspective is the correct concept because A narrative voice can disclose information from several characters'' minds. The model example is: Both traders privately feared that the storm would return. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Prose Narrators and Point of View\": Both traders privately feared that the storm would return?","options":[{"id":"A","text":"Omniscient perspective"},{"id":"B","text":"First-person viewpoint"},{"id":"C","text":"Third-person limited"},{"id":"D","text":"Unreliable narration"}],"answer":"A","explanation":"The example illustrates Omniscient perspective: A narrative voice can disclose information from several characters'' minds. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Prose Narrators and Point of View\", which literary concept matches this definition: A narrator''s account is limited or distorted in ways readers should question?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Third-person limited"},{"id":"C","text":"Omniscient perspective"},{"id":"D","text":"Unreliable narration"}],"answer":"D","explanation":"Unreliable narration is the correct concept because A narrator''s account is limited or distorted in ways readers should question. The model example is: I accused Efe of carelessness before learning why she stayed behind. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Prose Narrators and Point of View\": I accused Efe of carelessness before learning why she stayed behind?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Third-person limited"},{"id":"C","text":"Unreliable narration"},{"id":"D","text":"Omniscient perspective"}],"answer":"C","explanation":"The example illustrates Unreliable narration: A narrator''s account is limited or distorted in ways readers should question. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Prose Narrators and Point of View\", which literary concept matches this definition: The degree of closeness between the telling voice and events or emotions?","options":[{"id":"A","text":"First-person viewpoint"},{"id":"B","text":"Narrative distance"},{"id":"C","text":"Third-person limited"},{"id":"D","text":"Omniscient perspective"}],"answer":"B","explanation":"Narrative distance is the correct concept because The degree of closeness between the telling voice and events or emotions. The model example is: Years later, the narrator describes the same quarrel with detachment. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Prose Narrators and Point of View\": Years later, the narrator describes the same quarrel with detachment?","options":[{"id":"A","text":"Narrative distance"},{"id":"B","text":"First-person viewpoint"},{"id":"C","text":"Third-person limited"},{"id":"D","text":"Omniscient perspective"}],"answer":"A","explanation":"The example illustrates Narrative distance: The degree of closeness between the telling voice and events or emotions. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":2,"seq":2,"name":"Character Motivation and Conflict","slug":"lit-sss1-t2-character-motivation-and-conflict","code":"G26LITSSS1T2U2","body":"# Character Motivation and Conflict — SSS1 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nCharacters are understood through what they want, what blocks them and what they choose under pressure. Avoid describing a character as good or bad without citing decisions and consequences. Motivation can change as a story progresses.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> At the dry-season well, Kunle held a full bucket while a younger child waited. The water committee had limited each household to one turn. He looked at his mother''s empty container, then tipped half his bucket into the child''s cup. Their neighbour watched without speaking.\n\n## A worked close reading\nThe choice between family need and fairness creates a believable internal conflict. The neighbour''s silence does not establish agreement or disapproval. A strong answer explains how the action reveals a competing motive without inventing later events.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. External conflict\n**Meaning:** A character struggles against another person group or circumstance.\n**In practice:** The queue argues with Kunle over the water limit. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Internal conflict\n**Meaning:** Opposing impulses or values exist within one person.\n**In practice:** Kunle must choose between helping a child and filling his household bucket. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Motivation\n**Meaning:** A desire fear duty or need gives a character a reason to act.\n**In practice:** The need to carry water home shapes Kunle''s decision. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Character development\n**Meaning:** A character''s attitudes or choices change through events.\n**In practice:** A selfish pupil gradually learns to share resources. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Foil\n**Meaning:** Another character highlights a contrasting quality through comparison.\n**In practice:** A cautious sister makes her impulsive brother''s decisions stand out. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["External conflict: A character struggles against another person group or circumstance","Internal conflict: Opposing impulses or values exist within one person","Motivation: A desire fear duty or need gives a character a reason to act","Character development: A character''s attitudes or choices change through events","Foil: Another character highlights a contrasting quality through comparison"],"cards":[{"front":"What does \"External conflict\" mean in literary study?","back":"A character struggles against another person group or circumstance. Example: The queue argues with Kunle over the water limit.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Internal conflict\" mean in literary study?","back":"Opposing impulses or values exist within one person. Example: Kunle must choose between helping a child and filling his household bucket.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Motivation\" mean in literary study?","back":"A desire fear duty or need gives a character a reason to act. Example: The need to carry water home shapes Kunle''s decision.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Character development\" mean in literary study?","back":"A character''s attitudes or choices change through events. Example: A selfish pupil gradually learns to share resources.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Foil\" mean in literary study?","back":"Another character highlights a contrasting quality through comparison. Example: A cautious sister makes her impulsive brother''s decisions stand out.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate character motivation and conflict?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Character Motivation and Conflict\", which literary concept matches this definition: A character struggles against another person group or circumstance?","options":[{"id":"A","text":"Internal conflict"},{"id":"B","text":"Motivation"},{"id":"C","text":"Character development"},{"id":"D","text":"External conflict"}],"answer":"D","explanation":"External conflict is the correct concept because A character struggles against another person group or circumstance. The model example is: The queue argues with Kunle over the water limit. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Motivation and Conflict\": The queue argues with Kunle over the water limit?","options":[{"id":"A","text":"Internal conflict"},{"id":"B","text":"Motivation"},{"id":"C","text":"External conflict"},{"id":"D","text":"Character development"}],"answer":"C","explanation":"The example illustrates External conflict: A character struggles against another person group or circumstance. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Character Motivation and Conflict\", which literary concept matches this definition: Opposing impulses or values exist within one person?","options":[{"id":"A","text":"External conflict"},{"id":"B","text":"Internal conflict"},{"id":"C","text":"Motivation"},{"id":"D","text":"Character development"}],"answer":"B","explanation":"Internal conflict is the correct concept because Opposing impulses or values exist within one person. The model example is: Kunle must choose between helping a child and filling his household bucket. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Motivation and Conflict\": Kunle must choose between helping a child and filling his household bucket?","options":[{"id":"A","text":"Internal conflict"},{"id":"B","text":"External conflict"},{"id":"C","text":"Motivation"},{"id":"D","text":"Character development"}],"answer":"A","explanation":"The example illustrates Internal conflict: Opposing impulses or values exist within one person. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Character Motivation and Conflict\", which literary concept matches this definition: A desire fear duty or need gives a character a reason to act?","options":[{"id":"A","text":"External conflict"},{"id":"B","text":"Internal conflict"},{"id":"C","text":"Character development"},{"id":"D","text":"Motivation"}],"answer":"D","explanation":"Motivation is the correct concept because A desire fear duty or need gives a character a reason to act. The model example is: The need to carry water home shapes Kunle''s decision. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Motivation and Conflict\": The need to carry water home shapes Kunle''s decision?","options":[{"id":"A","text":"External conflict"},{"id":"B","text":"Internal conflict"},{"id":"C","text":"Motivation"},{"id":"D","text":"Character development"}],"answer":"C","explanation":"The example illustrates Motivation: A desire fear duty or need gives a character a reason to act. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Character Motivation and Conflict\", which literary concept matches this definition: A character''s attitudes or choices change through events?","options":[{"id":"A","text":"External conflict"},{"id":"B","text":"Character development"},{"id":"C","text":"Internal conflict"},{"id":"D","text":"Motivation"}],"answer":"B","explanation":"Character development is the correct concept because A character''s attitudes or choices change through events. The model example is: A selfish pupil gradually learns to share resources. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Motivation and Conflict\": A selfish pupil gradually learns to share resources?","options":[{"id":"A","text":"Character development"},{"id":"B","text":"External conflict"},{"id":"C","text":"Internal conflict"},{"id":"D","text":"Motivation"}],"answer":"A","explanation":"The example illustrates Character development: A character''s attitudes or choices change through events. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Character Motivation and Conflict\", which literary concept matches this definition: Another character highlights a contrasting quality through comparison?","options":[{"id":"A","text":"External conflict"},{"id":"B","text":"Internal conflict"},{"id":"C","text":"Motivation"},{"id":"D","text":"Foil"}],"answer":"D","explanation":"Foil is the correct concept because Another character highlights a contrasting quality through comparison. The model example is: A cautious sister makes her impulsive brother''s decisions stand out. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Motivation and Conflict\": A cautious sister makes her impulsive brother''s decisions stand out?","options":[{"id":"A","text":"External conflict"},{"id":"B","text":"Internal conflict"},{"id":"C","text":"Foil"},{"id":"D","text":"Motivation"}],"answer":"C","explanation":"The example illustrates Foil: Another character highlights a contrasting quality through comparison. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":2,"seq":3,"name":"Setting and Social Context","slug":"lit-sss1-t2-setting-and-social-context","code":"G26LITSSS1T2U3","body":"# Setting and Social Context — SSS1 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nSetting includes more than physical scenery. Time, local customs, weather, economic pressures and institutions can enable or restrict action. A writer can use setting as a source of conflict, atmosphere or symbolic meaning.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> The footbridge flooded before sunrise, cutting the traders off from the market. At the village square a sign announced new ferry charges. Miriam counted her coins twice and watched her baskets of tomatoes soften in the heat while officials argued over whose boat should cross first.\n\n## A worked close reading\nThe flooding is a physical obstacle; ferry charges are a social and economic pressure. The softening tomatoes add urgency through sensory detail. A response should link specific setting details to Miriam''s shrinking options rather than merely naming ''village'' as the setting.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Physical setting\n**Meaning:** The location landscape or built environment where events happen.\n**In practice:** The flooded bridge blocks travel to the market. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Temporal setting\n**Meaning:** The time period season or hour that shapes a scene.\n**In practice:** The crossing closes at sunrise during the rainy season. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Social setting\n**Meaning:** The customs institutions and relationships shaping characters'' opportunities.\n**In practice:** Ferry charges and local authority rules restrict traders. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Atmosphere\n**Meaning:** The emotional quality evoked by the scene''s details.\n**In practice:** Heat and delayed transport make the marketplace feel tense. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Setting as conflict\n**Meaning:** Environmental or social conditions directly oppose a character''s goal.\n**In practice:** Miriam must preserve produce while the bridge remains flooded. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Physical setting: The location landscape or built environment where events happen","Temporal setting: The time period season or hour that shapes a scene","Social setting: The customs institutions and relationships shaping characters'' opportunities","Atmosphere: The emotional quality evoked by the scene''s details","Setting as conflict: Environmental or social conditions directly oppose a character''s goal"],"cards":[{"front":"What does \"Physical setting\" mean in literary study?","back":"The location landscape or built environment where events happen. Example: The flooded bridge blocks travel to the market.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Temporal setting\" mean in literary study?","back":"The time period season or hour that shapes a scene. Example: The crossing closes at sunrise during the rainy season.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Social setting\" mean in literary study?","back":"The customs institutions and relationships shaping characters'' opportunities. Example: Ferry charges and local authority rules restrict traders.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Atmosphere\" mean in literary study?","back":"The emotional quality evoked by the scene''s details. Example: Heat and delayed transport make the marketplace feel tense.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Setting as conflict\" mean in literary study?","back":"Environmental or social conditions directly oppose a character''s goal. Example: Miriam must preserve produce while the bridge remains flooded.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate setting and social context?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Setting and Social Context\", which literary concept matches this definition: The location landscape or built environment where events happen?","options":[{"id":"A","text":"Temporal setting"},{"id":"B","text":"Physical setting"},{"id":"C","text":"Social setting"},{"id":"D","text":"Atmosphere"}],"answer":"B","explanation":"Physical setting is the correct concept because The location landscape or built environment where events happen. The model example is: The flooded bridge blocks travel to the market. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Setting and Social Context\": The flooded bridge blocks travel to the market?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Temporal setting"},{"id":"C","text":"Social setting"},{"id":"D","text":"Atmosphere"}],"answer":"A","explanation":"The example illustrates Physical setting: The location landscape or built environment where events happen. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Setting and Social Context\", which literary concept matches this definition: The time period season or hour that shapes a scene?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Social setting"},{"id":"C","text":"Atmosphere"},{"id":"D","text":"Temporal setting"}],"answer":"D","explanation":"Temporal setting is the correct concept because The time period season or hour that shapes a scene. The model example is: The crossing closes at sunrise during the rainy season. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Setting and Social Context\": The crossing closes at sunrise during the rainy season?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Social setting"},{"id":"C","text":"Temporal setting"},{"id":"D","text":"Atmosphere"}],"answer":"C","explanation":"The example illustrates Temporal setting: The time period season or hour that shapes a scene. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Setting and Social Context\", which literary concept matches this definition: The customs institutions and relationships shaping characters'' opportunities?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Social setting"},{"id":"C","text":"Temporal setting"},{"id":"D","text":"Atmosphere"}],"answer":"B","explanation":"Social setting is the correct concept because The customs institutions and relationships shaping characters'' opportunities. The model example is: Ferry charges and local authority rules restrict traders. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Setting and Social Context\": Ferry charges and local authority rules restrict traders?","options":[{"id":"A","text":"Social setting"},{"id":"B","text":"Physical setting"},{"id":"C","text":"Temporal setting"},{"id":"D","text":"Atmosphere"}],"answer":"A","explanation":"The example illustrates Social setting: The customs institutions and relationships shaping characters'' opportunities. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Setting and Social Context\", which literary concept matches this definition: The emotional quality evoked by the scene''s details?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Temporal setting"},{"id":"C","text":"Social setting"},{"id":"D","text":"Atmosphere"}],"answer":"D","explanation":"Atmosphere is the correct concept because The emotional quality evoked by the scene''s details. The model example is: Heat and delayed transport make the marketplace feel tense. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Setting and Social Context\": Heat and delayed transport make the marketplace feel tense?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Temporal setting"},{"id":"C","text":"Atmosphere"},{"id":"D","text":"Social setting"}],"answer":"C","explanation":"The example illustrates Atmosphere: The emotional quality evoked by the scene''s details. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Setting and Social Context\", which literary concept matches this definition: Environmental or social conditions directly oppose a character''s goal?","options":[{"id":"A","text":"Physical setting"},{"id":"B","text":"Setting as conflict"},{"id":"C","text":"Temporal setting"},{"id":"D","text":"Social setting"}],"answer":"B","explanation":"Setting as conflict is the correct concept because Environmental or social conditions directly oppose a character''s goal. The model example is: Miriam must preserve produce while the bridge remains flooded. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Setting and Social Context\": Miriam must preserve produce while the bridge remains flooded?","options":[{"id":"A","text":"Setting as conflict"},{"id":"B","text":"Physical setting"},{"id":"C","text":"Temporal setting"},{"id":"D","text":"Social setting"}],"answer":"A","explanation":"The example illustrates Setting as conflict: Environmental or social conditions directly oppose a character''s goal. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":2,"seq":4,"name":"Imagery and Tone in Poetry","slug":"lit-sss1-t2-imagery-and-tone-in-poetry","code":"G26LITSSS1T2U4","body":"# Imagery and Tone in Poetry — SSS1 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nPoetry can convey meaning through concrete sensory impressions and carefully chosen words. Separate imagery from speaker tone: images describe or evoke experience, whereas tone concerns the attitude communicated by the voice.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Red dust settled on the classroom sill. Beyond the window, a tired bell coughed once and fell quiet. I held my examination slip as gently as a seed, unsure which road its small numbers would open.\n\n## A worked close reading\nDust and the coughing bell create sensory imagery; the seed simile suggests fragile possibility. The word ''unsure'' supports a hesitant tone. An interpretation that the speaker is definitely triumphant would exceed the evidence.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Visual imagery\n**Meaning:** Language evokes colours shapes light or movement seen by the mind.\n**In practice:** Red dust lay across the classroom sill. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Auditory imagery\n**Meaning:** Words call up heard sounds or silence.\n**In practice:** The bell coughed once and grew quiet. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Tactile imagery\n**Meaning:** Description invites an impression of touch texture or temperature.\n**In practice:** The cold slip trembled between damp fingers. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Tone\n**Meaning:** The attitude revealed by the speaker''s diction and voice.\n**In practice:** Unsure gives the reflection a cautious rather than boastful voice. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Simile\n**Meaning:** A direct comparison commonly marked with like or as.\n**In practice:** I held the result as gently as a seed. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Visual imagery: Language evokes colours shapes light or movement seen by the mind","Auditory imagery: Words call up heard sounds or silence","Tactile imagery: Description invites an impression of touch texture or temperature","Tone: The attitude revealed by the speaker''s diction and voice","Simile: A direct comparison commonly marked with like or as"],"cards":[{"front":"What does \"Visual imagery\" mean in literary study?","back":"Language evokes colours shapes light or movement seen by the mind. Example: Red dust lay across the classroom sill.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Auditory imagery\" mean in literary study?","back":"Words call up heard sounds or silence. Example: The bell coughed once and grew quiet.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Tactile imagery\" mean in literary study?","back":"Description invites an impression of touch texture or temperature. Example: The cold slip trembled between damp fingers.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Tone\" mean in literary study?","back":"The attitude revealed by the speaker''s diction and voice. Example: Unsure gives the reflection a cautious rather than boastful voice.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Simile\" mean in literary study?","back":"A direct comparison commonly marked with like or as. Example: I held the result as gently as a seed.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate imagery and tone in poetry?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Imagery and Tone in Poetry\", which literary concept matches this definition: Language evokes colours shapes light or movement seen by the mind?","options":[{"id":"A","text":"Auditory imagery"},{"id":"B","text":"Tactile imagery"},{"id":"C","text":"Tone"},{"id":"D","text":"Visual imagery"}],"answer":"D","explanation":"Visual imagery is the correct concept because Language evokes colours shapes light or movement seen by the mind. The model example is: Red dust lay across the classroom sill. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Imagery and Tone in Poetry\": Red dust lay across the classroom sill?","options":[{"id":"A","text":"Auditory imagery"},{"id":"B","text":"Tactile imagery"},{"id":"C","text":"Visual imagery"},{"id":"D","text":"Tone"}],"answer":"C","explanation":"The example illustrates Visual imagery: Language evokes colours shapes light or movement seen by the mind. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Imagery and Tone in Poetry\", which literary concept matches this definition: Words call up heard sounds or silence?","options":[{"id":"A","text":"Visual imagery"},{"id":"B","text":"Auditory imagery"},{"id":"C","text":"Tactile imagery"},{"id":"D","text":"Tone"}],"answer":"B","explanation":"Auditory imagery is the correct concept because Words call up heard sounds or silence. The model example is: The bell coughed once and grew quiet. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Imagery and Tone in Poetry\": The bell coughed once and grew quiet?","options":[{"id":"A","text":"Auditory imagery"},{"id":"B","text":"Visual imagery"},{"id":"C","text":"Tactile imagery"},{"id":"D","text":"Tone"}],"answer":"A","explanation":"The example illustrates Auditory imagery: Words call up heard sounds or silence. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Imagery and Tone in Poetry\", which literary concept matches this definition: Description invites an impression of touch texture or temperature?","options":[{"id":"A","text":"Visual imagery"},{"id":"B","text":"Auditory imagery"},{"id":"C","text":"Tone"},{"id":"D","text":"Tactile imagery"}],"answer":"D","explanation":"Tactile imagery is the correct concept because Description invites an impression of touch texture or temperature. The model example is: The cold slip trembled between damp fingers. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Imagery and Tone in Poetry\": The cold slip trembled between damp fingers?","options":[{"id":"A","text":"Visual imagery"},{"id":"B","text":"Auditory imagery"},{"id":"C","text":"Tactile imagery"},{"id":"D","text":"Tone"}],"answer":"C","explanation":"The example illustrates Tactile imagery: Description invites an impression of touch texture or temperature. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Imagery and Tone in Poetry\", which literary concept matches this definition: The attitude revealed by the speaker''s diction and voice?","options":[{"id":"A","text":"Visual imagery"},{"id":"B","text":"Tone"},{"id":"C","text":"Auditory imagery"},{"id":"D","text":"Tactile imagery"}],"answer":"B","explanation":"Tone is the correct concept because The attitude revealed by the speaker''s diction and voice. The model example is: Unsure gives the reflection a cautious rather than boastful voice. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Imagery and Tone in Poetry\": Unsure gives the reflection a cautious rather than boastful voice?","options":[{"id":"A","text":"Tone"},{"id":"B","text":"Visual imagery"},{"id":"C","text":"Auditory imagery"},{"id":"D","text":"Tactile imagery"}],"answer":"A","explanation":"The example illustrates Tone: The attitude revealed by the speaker''s diction and voice. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Imagery and Tone in Poetry\", which literary concept matches this definition: A direct comparison commonly marked with like or as?","options":[{"id":"A","text":"Visual imagery"},{"id":"B","text":"Auditory imagery"},{"id":"C","text":"Tactile imagery"},{"id":"D","text":"Simile"}],"answer":"D","explanation":"Simile is the correct concept because A direct comparison commonly marked with like or as. The model example is: I held the result as gently as a seed. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Imagery and Tone in Poetry\": I held the result as gently as a seed?","options":[{"id":"A","text":"Visual imagery"},{"id":"B","text":"Auditory imagery"},{"id":"C","text":"Simile"},{"id":"D","text":"Tactile imagery"}],"answer":"C","explanation":"The example illustrates Simile: A direct comparison commonly marked with like or as. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":2,"seq":5,"name":"Oral Storytelling and Performance","slug":"lit-sss1-t2-oral-storytelling-and-performance","code":"G26LITSSS1T2U5","body":"# Oral Storytelling and Performance — SSS1 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nOral literature belongs to a live relationship between teller and audience. Voice, pauses, refrains, gesture and responses can influence meaning. A printed transcript may capture words but lose timing and bodily movement.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> The storyteller lifted an empty calabash. ''Who will fill it?'' she asked. Children answered, ''Those who care!'' After a pause she placed the vessel between two arguing neighbours. This time no child responded, and the storyteller lowered her voice.\n\n## A worked close reading\nThe first exchange is call-and-response, while the silence changes the performance''s mood. The calabash is a visible object with possible symbolic importance. Do not attribute this invented example to any Nigerian ethnic community.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Call-and-response\n**Meaning:** A performer invites an audience to answer a repeated cue.\n**In practice:** Who will fill it is answered by Those who care. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Refrain\n**Meaning:** A repeated phrase or line helps structure participation.\n**In practice:** The same chorus returns after each short episode. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Performance pause\n**Meaning:** Deliberate silence changes anticipation emphasis or feeling.\n**In practice:** The storyteller waits after placing the calabash. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Gesture\n**Meaning:** Body movement communicates meaning alongside words.\n**In practice:** She raises the empty vessel for the whole audience to see. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Oral variation\n**Meaning:** Repeated performances may differ in details for different audiences.\n**In practice:** A teller adjusts a character''s dialogue for a new village audience. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Call-and-response: A performer invites an audience to answer a repeated cue","Refrain: A repeated phrase or line helps structure participation","Performance pause: Deliberate silence changes anticipation emphasis or feeling","Gesture: Body movement communicates meaning alongside words","Oral variation: Repeated performances may differ in details for different audiences"],"cards":[{"front":"What does \"Call-and-response\" mean in literary study?","back":"A performer invites an audience to answer a repeated cue. Example: Who will fill it is answered by Those who care.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Refrain\" mean in literary study?","back":"A repeated phrase or line helps structure participation. Example: The same chorus returns after each short episode.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Performance pause\" mean in literary study?","back":"Deliberate silence changes anticipation emphasis or feeling. Example: The storyteller waits after placing the calabash.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Gesture\" mean in literary study?","back":"Body movement communicates meaning alongside words. Example: She raises the empty vessel for the whole audience to see.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Oral variation\" mean in literary study?","back":"Repeated performances may differ in details for different audiences. Example: A teller adjusts a character''s dialogue for a new village audience.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate oral storytelling and performance?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Oral Storytelling and Performance\", which literary concept matches this definition: A performer invites an audience to answer a repeated cue?","options":[{"id":"A","text":"Refrain"},{"id":"B","text":"Call-and-response"},{"id":"C","text":"Performance pause"},{"id":"D","text":"Gesture"}],"answer":"B","explanation":"Call-and-response is the correct concept because A performer invites an audience to answer a repeated cue. The model example is: Who will fill it is answered by Those who care. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Oral Storytelling and Performance\": Who will fill it is answered by Those who care?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Refrain"},{"id":"C","text":"Performance pause"},{"id":"D","text":"Gesture"}],"answer":"A","explanation":"The example illustrates Call-and-response: A performer invites an audience to answer a repeated cue. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Oral Storytelling and Performance\", which literary concept matches this definition: A repeated phrase or line helps structure participation?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Performance pause"},{"id":"C","text":"Gesture"},{"id":"D","text":"Refrain"}],"answer":"D","explanation":"Refrain is the correct concept because A repeated phrase or line helps structure participation. The model example is: The same chorus returns after each short episode. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Oral Storytelling and Performance\": The same chorus returns after each short episode?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Performance pause"},{"id":"C","text":"Refrain"},{"id":"D","text":"Gesture"}],"answer":"C","explanation":"The example illustrates Refrain: A repeated phrase or line helps structure participation. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Oral Storytelling and Performance\", which literary concept matches this definition: Deliberate silence changes anticipation emphasis or feeling?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Performance pause"},{"id":"C","text":"Refrain"},{"id":"D","text":"Gesture"}],"answer":"B","explanation":"Performance pause is the correct concept because Deliberate silence changes anticipation emphasis or feeling. The model example is: The storyteller waits after placing the calabash. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Oral Storytelling and Performance\": The storyteller waits after placing the calabash?","options":[{"id":"A","text":"Performance pause"},{"id":"B","text":"Call-and-response"},{"id":"C","text":"Refrain"},{"id":"D","text":"Gesture"}],"answer":"A","explanation":"The example illustrates Performance pause: Deliberate silence changes anticipation emphasis or feeling. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Oral Storytelling and Performance\", which literary concept matches this definition: Body movement communicates meaning alongside words?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Refrain"},{"id":"C","text":"Performance pause"},{"id":"D","text":"Gesture"}],"answer":"D","explanation":"Gesture is the correct concept because Body movement communicates meaning alongside words. The model example is: She raises the empty vessel for the whole audience to see. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Oral Storytelling and Performance\": She raises the empty vessel for the whole audience to see?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Refrain"},{"id":"C","text":"Gesture"},{"id":"D","text":"Performance pause"}],"answer":"C","explanation":"The example illustrates Gesture: Body movement communicates meaning alongside words. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Oral Storytelling and Performance\", which literary concept matches this definition: Repeated performances may differ in details for different audiences?","options":[{"id":"A","text":"Call-and-response"},{"id":"B","text":"Oral variation"},{"id":"C","text":"Refrain"},{"id":"D","text":"Performance pause"}],"answer":"B","explanation":"Oral variation is the correct concept because Repeated performances may differ in details for different audiences. The model example is: A teller adjusts a character''s dialogue for a new village audience. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Oral Storytelling and Performance\": A teller adjusts a character''s dialogue for a new village audience?","options":[{"id":"A","text":"Oral variation"},{"id":"B","text":"Call-and-response"},{"id":"C","text":"Refrain"},{"id":"D","text":"Performance pause"}],"answer":"A","explanation":"The example illustrates Oral variation: Repeated performances may differ in details for different audiences. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":3,"seq":1,"name":"Subtext in Dramatic Dialogue","slug":"lit-sss1-t3-subtext-in-dramatic-dialogue","code":"G26LITSSS1T3U1","body":"# Subtext in Dramatic Dialogue — SSS1 Literature in English, Third Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nDrama often places what a character says beside what a character actually wants. Subtext is the meaning a viewer infers beneath the surface of the dialogue. Performance details can support the inference, but a guess should remain distinct from a stated fact.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> ADA: You have returned the key? BOLA: The door is open. (He hides his hand behind his back.) ADA: That is not what I asked. BOLA: It is what you need to know. (A light flickers.)\n\n## A worked close reading\nBola evades the question rather than confirming possession of the key. The hidden hand can suggest concealment, but cannot prove that he stole anything. A successful interpretation identifies the evasive answer and its effect on tension.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Subtext\n**Meaning:** Meaning implied under spoken dialogue rather than directly declared.\n**In practice:** Bola''s evasive response hints that he is withholding information. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Dialogue\n**Meaning:** Words exchanged by characters on stage.\n**In practice:** Ada asks a question and Bola replies indirectly. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Stage direction\n**Meaning:** A script instruction for movement sound gesture or light.\n**In practice:** He hides his hand behind his back. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Dramatic tension\n**Meaning:** Uncertainty or opposition makes the audience anticipate what happens next.\n**In practice:** The missing key and evasive response keep Ada suspicious. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Pause\n**Meaning:** A deliberate break in performance can reveal hesitation or strain.\n**In practice:** Bola stays silent before answering Ada''s question. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Subtext: Meaning implied under spoken dialogue rather than directly declared","Dialogue: Words exchanged by characters on stage","Stage direction: A script instruction for movement sound gesture or light","Dramatic tension: Uncertainty or opposition makes the audience anticipate what happens next","Pause: A deliberate break in performance can reveal hesitation or strain"],"cards":[{"front":"What does \"Subtext\" mean in literary study?","back":"Meaning implied under spoken dialogue rather than directly declared. Example: Bola''s evasive response hints that he is withholding information.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Dialogue\" mean in literary study?","back":"Words exchanged by characters on stage. Example: Ada asks a question and Bola replies indirectly.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Stage direction\" mean in literary study?","back":"A script instruction for movement sound gesture or light. Example: He hides his hand behind his back.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Dramatic tension\" mean in literary study?","back":"Uncertainty or opposition makes the audience anticipate what happens next. Example: The missing key and evasive response keep Ada suspicious.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Pause\" mean in literary study?","back":"A deliberate break in performance can reveal hesitation or strain. Example: Bola stays silent before answering Ada''s question.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate subtext in dramatic dialogue?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Subtext in Dramatic Dialogue\", which literary concept matches this definition: Meaning implied under spoken dialogue rather than directly declared?","options":[{"id":"A","text":"Dialogue"},{"id":"B","text":"Stage direction"},{"id":"C","text":"Dramatic tension"},{"id":"D","text":"Subtext"}],"answer":"D","explanation":"Subtext is the correct concept because Meaning implied under spoken dialogue rather than directly declared. The model example is: Bola''s evasive response hints that he is withholding information. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Subtext in Dramatic Dialogue\": Bola''s evasive response hints that he is withholding information?","options":[{"id":"A","text":"Dialogue"},{"id":"B","text":"Stage direction"},{"id":"C","text":"Subtext"},{"id":"D","text":"Dramatic tension"}],"answer":"C","explanation":"The example illustrates Subtext: Meaning implied under spoken dialogue rather than directly declared. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Subtext in Dramatic Dialogue\", which literary concept matches this definition: Words exchanged by characters on stage?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Dialogue"},{"id":"C","text":"Stage direction"},{"id":"D","text":"Dramatic tension"}],"answer":"B","explanation":"Dialogue is the correct concept because Words exchanged by characters on stage. The model example is: Ada asks a question and Bola replies indirectly. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Subtext in Dramatic Dialogue\": Ada asks a question and Bola replies indirectly?","options":[{"id":"A","text":"Dialogue"},{"id":"B","text":"Subtext"},{"id":"C","text":"Stage direction"},{"id":"D","text":"Dramatic tension"}],"answer":"A","explanation":"The example illustrates Dialogue: Words exchanged by characters on stage. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Subtext in Dramatic Dialogue\", which literary concept matches this definition: A script instruction for movement sound gesture or light?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Dialogue"},{"id":"C","text":"Dramatic tension"},{"id":"D","text":"Stage direction"}],"answer":"D","explanation":"Stage direction is the correct concept because A script instruction for movement sound gesture or light. The model example is: He hides his hand behind his back. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Subtext in Dramatic Dialogue\": He hides his hand behind his back?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Dialogue"},{"id":"C","text":"Stage direction"},{"id":"D","text":"Dramatic tension"}],"answer":"C","explanation":"The example illustrates Stage direction: A script instruction for movement sound gesture or light. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Subtext in Dramatic Dialogue\", which literary concept matches this definition: Uncertainty or opposition makes the audience anticipate what happens next?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Dramatic tension"},{"id":"C","text":"Dialogue"},{"id":"D","text":"Stage direction"}],"answer":"B","explanation":"Dramatic tension is the correct concept because Uncertainty or opposition makes the audience anticipate what happens next. The model example is: The missing key and evasive response keep Ada suspicious. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Subtext in Dramatic Dialogue\": The missing key and evasive response keep Ada suspicious?","options":[{"id":"A","text":"Dramatic tension"},{"id":"B","text":"Subtext"},{"id":"C","text":"Dialogue"},{"id":"D","text":"Stage direction"}],"answer":"A","explanation":"The example illustrates Dramatic tension: Uncertainty or opposition makes the audience anticipate what happens next. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Subtext in Dramatic Dialogue\", which literary concept matches this definition: A deliberate break in performance can reveal hesitation or strain?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Dialogue"},{"id":"C","text":"Stage direction"},{"id":"D","text":"Pause"}],"answer":"D","explanation":"Pause is the correct concept because A deliberate break in performance can reveal hesitation or strain. The model example is: Bola stays silent before answering Ada''s question. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Subtext in Dramatic Dialogue\": Bola stays silent before answering Ada''s question?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Dialogue"},{"id":"C","text":"Pause"},{"id":"D","text":"Stage direction"}],"answer":"C","explanation":"The example illustrates Pause: A deliberate break in performance can reveal hesitation or strain. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":3,"seq":2,"name":"Acts Scenes and Dramatic Progression","slug":"lit-sss1-t3-acts-scenes-and-dramatic-progression","code":"G26LITSSS1T3U2","body":"# Acts Scenes and Dramatic Progression — SSS1 Literature in English, Third Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nAnalyse how a play organises turning points rather than memorising the labels of its divisions. An act can contain several scenes; a new scene may shift place, time or the characters present.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> In Scene One, two students promise to bring an umbrella to a school play. In Scene Two, the rehearsal room is wet and the umbrella is missing. A messenger announces that rain has blocked the road; the production manager changes the rehearsal plan.\n\n## A worked close reading\nThe shift of scene brings a practical obstacle into focus. A promising beginning becomes a conflict, and the manager''s adaptation is a new dramatic action. There is no basis to assume the umbrella was stolen.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Act\n**Meaning:** A broad structural division of a play that may contain multiple scenes.\n**In practice:** Act Two develops the consequences of the failed rehearsal. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Scene\n**Meaning:** A smaller division often marked by a shift of place time or characters.\n**In practice:** The action moves from the courtyard to the wet rehearsal room. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Exposition\n**Meaning:** Opening information establishes people circumstances and expectations.\n**In practice:** The first scene explains who is responsible for the umbrella. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Complication\n**Meaning:** An obstacle intensifies the dramatic situation.\n**In practice:** The umbrella disappears as a storm blocks the road. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Turning point\n**Meaning:** An event or decision redirects the action.\n**In practice:** The manager changes the plan after receiving the messenger''s news. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Act: A broad structural division of a play that may contain multiple scenes","Scene: A smaller division often marked by a shift of place time or characters","Exposition: Opening information establishes people circumstances and expectations","Complication: An obstacle intensifies the dramatic situation","Turning point: An event or decision redirects the action"],"cards":[{"front":"What does \"Act\" mean in literary study?","back":"A broad structural division of a play that may contain multiple scenes. Example: Act Two develops the consequences of the failed rehearsal.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Scene\" mean in literary study?","back":"A smaller division often marked by a shift of place time or characters. Example: The action moves from the courtyard to the wet rehearsal room.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Exposition\" mean in literary study?","back":"Opening information establishes people circumstances and expectations. Example: The first scene explains who is responsible for the umbrella.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Complication\" mean in literary study?","back":"An obstacle intensifies the dramatic situation. Example: The umbrella disappears as a storm blocks the road.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Turning point\" mean in literary study?","back":"An event or decision redirects the action. Example: The manager changes the plan after receiving the messenger''s news.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate acts scenes and dramatic progression?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Acts Scenes and Dramatic Progression\", which literary concept matches this definition: A broad structural division of a play that may contain multiple scenes?","options":[{"id":"A","text":"Scene"},{"id":"B","text":"Act"},{"id":"C","text":"Exposition"},{"id":"D","text":"Complication"}],"answer":"B","explanation":"Act is the correct concept because A broad structural division of a play that may contain multiple scenes. The model example is: Act Two develops the consequences of the failed rehearsal. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Acts Scenes and Dramatic Progression\": Act Two develops the consequences of the failed rehearsal?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Scene"},{"id":"C","text":"Exposition"},{"id":"D","text":"Complication"}],"answer":"A","explanation":"The example illustrates Act: A broad structural division of a play that may contain multiple scenes. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Acts Scenes and Dramatic Progression\", which literary concept matches this definition: A smaller division often marked by a shift of place time or characters?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Exposition"},{"id":"C","text":"Complication"},{"id":"D","text":"Scene"}],"answer":"D","explanation":"Scene is the correct concept because A smaller division often marked by a shift of place time or characters. The model example is: The action moves from the courtyard to the wet rehearsal room. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Acts Scenes and Dramatic Progression\": The action moves from the courtyard to the wet rehearsal room?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Exposition"},{"id":"C","text":"Scene"},{"id":"D","text":"Complication"}],"answer":"C","explanation":"The example illustrates Scene: A smaller division often marked by a shift of place time or characters. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Acts Scenes and Dramatic Progression\", which literary concept matches this definition: Opening information establishes people circumstances and expectations?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Exposition"},{"id":"C","text":"Scene"},{"id":"D","text":"Complication"}],"answer":"B","explanation":"Exposition is the correct concept because Opening information establishes people circumstances and expectations. The model example is: The first scene explains who is responsible for the umbrella. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Acts Scenes and Dramatic Progression\": The first scene explains who is responsible for the umbrella?","options":[{"id":"A","text":"Exposition"},{"id":"B","text":"Act"},{"id":"C","text":"Scene"},{"id":"D","text":"Complication"}],"answer":"A","explanation":"The example illustrates Exposition: Opening information establishes people circumstances and expectations. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Acts Scenes and Dramatic Progression\", which literary concept matches this definition: An obstacle intensifies the dramatic situation?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Scene"},{"id":"C","text":"Exposition"},{"id":"D","text":"Complication"}],"answer":"D","explanation":"Complication is the correct concept because An obstacle intensifies the dramatic situation. The model example is: The umbrella disappears as a storm blocks the road. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Acts Scenes and Dramatic Progression\": The umbrella disappears as a storm blocks the road?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Scene"},{"id":"C","text":"Complication"},{"id":"D","text":"Exposition"}],"answer":"C","explanation":"The example illustrates Complication: An obstacle intensifies the dramatic situation. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Acts Scenes and Dramatic Progression\", which literary concept matches this definition: An event or decision redirects the action?","options":[{"id":"A","text":"Act"},{"id":"B","text":"Turning point"},{"id":"C","text":"Scene"},{"id":"D","text":"Exposition"}],"answer":"B","explanation":"Turning point is the correct concept because An event or decision redirects the action. The model example is: The manager changes the plan after receiving the messenger''s news. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Acts Scenes and Dramatic Progression\": The manager changes the plan after receiving the messenger''s news?","options":[{"id":"A","text":"Turning point"},{"id":"B","text":"Act"},{"id":"C","text":"Scene"},{"id":"D","text":"Exposition"}],"answer":"A","explanation":"The example illustrates Turning point: An event or decision redirects the action. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":3,"seq":3,"name":"Lyric Narrative and Dramatic Poetry","slug":"lit-sss1-t3-lyric-narrative-and-dramatic-poetry","code":"G26LITSSS1T3U3","body":"# Lyric Narrative and Dramatic Poetry — SSS1 Literature in English, Third Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nPoems may present emotion, tell a sequence of events or stage a speaking persona. These functions can overlap, so identify the dominant form and supply supporting details rather than force a classification from the length alone.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> A traveller speaks: ''I walked beyond the station gate / And counted lamps until the late / Train left me standing in the rain. / I will not miss that chance again.'' The voice recounts movement while expressing regret.\n\n## A worked close reading\nThe poem has narrative movement and an inward response. The speaker recounts a train departing; first-person expression does not prove the poet personally missed a train. A shorter lyric could focus only on the feeling of regret.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Lyric poetry\n**Meaning:** A poem chiefly expressing a speaker''s feeling reflection or perspective.\n**In practice:** A short voice meditates on regret after missing a train. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Narrative poetry\n**Meaning:** Verse tells events or action with development through time.\n**In practice:** The traveller walks counts lamps and watches a train leave. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Dramatic monologue\n**Meaning:** A single speaking persona addresses an implied listener revealing character.\n**In practice:** An imagined conductor speaks to passengers about his past choices. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Persona\n**Meaning:** The voice or role adopted within a poem need not be the poet.\n**In practice:** A young traveller says I while an older writer created the lines. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Stanza\n**Meaning:** A grouped unit of poetic lines contributing to structure and rhythm.\n**In practice:** Four lines form one visible group before the next movement. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Lyric poetry: A poem chiefly expressing a speaker''s feeling reflection or perspective","Narrative poetry: Verse tells events or action with development through time","Dramatic monologue: A single speaking persona addresses an implied listener revealing character","Persona: The voice or role adopted within a poem need not be the poet","Stanza: A grouped unit of poetic lines contributing to structure and rhythm"],"cards":[{"front":"What does \"Lyric poetry\" mean in literary study?","back":"A poem chiefly expressing a speaker''s feeling reflection or perspective. Example: A short voice meditates on regret after missing a train.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Narrative poetry\" mean in literary study?","back":"Verse tells events or action with development through time. Example: The traveller walks counts lamps and watches a train leave.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Dramatic monologue\" mean in literary study?","back":"A single speaking persona addresses an implied listener revealing character. Example: An imagined conductor speaks to passengers about his past choices.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Persona\" mean in literary study?","back":"The voice or role adopted within a poem need not be the poet. Example: A young traveller says I while an older writer created the lines.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Stanza\" mean in literary study?","back":"A grouped unit of poetic lines contributing to structure and rhythm. Example: Four lines form one visible group before the next movement.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate lyric narrative and dramatic poetry?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Lyric Narrative and Dramatic Poetry\", which literary concept matches this definition: A poem chiefly expressing a speaker''s feeling reflection or perspective?","options":[{"id":"A","text":"Narrative poetry"},{"id":"B","text":"Dramatic monologue"},{"id":"C","text":"Persona"},{"id":"D","text":"Lyric poetry"}],"answer":"D","explanation":"Lyric poetry is the correct concept because A poem chiefly expressing a speaker''s feeling reflection or perspective. The model example is: A short voice meditates on regret after missing a train. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Lyric Narrative and Dramatic Poetry\": A short voice meditates on regret after missing a train?","options":[{"id":"A","text":"Narrative poetry"},{"id":"B","text":"Dramatic monologue"},{"id":"C","text":"Lyric poetry"},{"id":"D","text":"Persona"}],"answer":"C","explanation":"The example illustrates Lyric poetry: A poem chiefly expressing a speaker''s feeling reflection or perspective. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Lyric Narrative and Dramatic Poetry\", which literary concept matches this definition: Verse tells events or action with development through time?","options":[{"id":"A","text":"Lyric poetry"},{"id":"B","text":"Narrative poetry"},{"id":"C","text":"Dramatic monologue"},{"id":"D","text":"Persona"}],"answer":"B","explanation":"Narrative poetry is the correct concept because Verse tells events or action with development through time. The model example is: The traveller walks counts lamps and watches a train leave. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Lyric Narrative and Dramatic Poetry\": The traveller walks counts lamps and watches a train leave?","options":[{"id":"A","text":"Narrative poetry"},{"id":"B","text":"Lyric poetry"},{"id":"C","text":"Dramatic monologue"},{"id":"D","text":"Persona"}],"answer":"A","explanation":"The example illustrates Narrative poetry: Verse tells events or action with development through time. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Lyric Narrative and Dramatic Poetry\", which literary concept matches this definition: A single speaking persona addresses an implied listener revealing character?","options":[{"id":"A","text":"Lyric poetry"},{"id":"B","text":"Narrative poetry"},{"id":"C","text":"Persona"},{"id":"D","text":"Dramatic monologue"}],"answer":"D","explanation":"Dramatic monologue is the correct concept because A single speaking persona addresses an implied listener revealing character. The model example is: An imagined conductor speaks to passengers about his past choices. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Lyric Narrative and Dramatic Poetry\": An imagined conductor speaks to passengers about his past choices?","options":[{"id":"A","text":"Lyric poetry"},{"id":"B","text":"Narrative poetry"},{"id":"C","text":"Dramatic monologue"},{"id":"D","text":"Persona"}],"answer":"C","explanation":"The example illustrates Dramatic monologue: A single speaking persona addresses an implied listener revealing character. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Lyric Narrative and Dramatic Poetry\", which literary concept matches this definition: The voice or role adopted within a poem need not be the poet?","options":[{"id":"A","text":"Lyric poetry"},{"id":"B","text":"Persona"},{"id":"C","text":"Narrative poetry"},{"id":"D","text":"Dramatic monologue"}],"answer":"B","explanation":"Persona is the correct concept because The voice or role adopted within a poem need not be the poet. The model example is: A young traveller says I while an older writer created the lines. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Lyric Narrative and Dramatic Poetry\": A young traveller says I while an older writer created the lines?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Lyric poetry"},{"id":"C","text":"Narrative poetry"},{"id":"D","text":"Dramatic monologue"}],"answer":"A","explanation":"The example illustrates Persona: The voice or role adopted within a poem need not be the poet. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Lyric Narrative and Dramatic Poetry\", which literary concept matches this definition: A grouped unit of poetic lines contributing to structure and rhythm?","options":[{"id":"A","text":"Lyric poetry"},{"id":"B","text":"Narrative poetry"},{"id":"C","text":"Dramatic monologue"},{"id":"D","text":"Stanza"}],"answer":"D","explanation":"Stanza is the correct concept because A grouped unit of poetic lines contributing to structure and rhythm. The model example is: Four lines form one visible group before the next movement. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Lyric Narrative and Dramatic Poetry\": Four lines form one visible group before the next movement?","options":[{"id":"A","text":"Lyric poetry"},{"id":"B","text":"Narrative poetry"},{"id":"C","text":"Stanza"},{"id":"D","text":"Dramatic monologue"}],"answer":"C","explanation":"The example illustrates Stanza: A grouped unit of poetic lines contributing to structure and rhythm. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":3,"seq":4,"name":"Plot Sequence and Flashback","slug":"lit-sss1-t3-plot-sequence-and-flashback","code":"G26LITSSS1T3U4","body":"# Plot Sequence and Flashback — SSS1 Literature in English, Third Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nReaders should track the order in which events occurred and the order in which a narrator reveals them. The two orders may differ intentionally to create curiosity, suspense or a reassessment of earlier evidence.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Tuesday: Halima discovers a torn map in the school cupboard. The chapter then returns to Friday when the geography club loaned that map to the visitors. The narration moves back to Tuesday as she asks who last signed the register.\n\n## A worked close reading\nThe movement from Tuesday to an earlier Friday is a flashback. It provides historical context without proving who tore the map. A chronology chart helps to separate narrative sequence from actual event sequence.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Chronology\n**Meaning:** The order in which events actually occur in story time.\n**In practice:** Friday''s loan happened before Tuesday''s discovery. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Flashback\n**Meaning:** A shift in narration to an earlier event.\n**In practice:** The chapter returns from Tuesday to the previous Friday. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Foreshadowing\n**Meaning:** A clue or suggestion that prepares the reader for a later event.\n**In practice:** A warning about fragile maps hints at a later problem. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Suspense\n**Meaning:** Uncertainty about an outcome sustains reader interest.\n**In practice:** The register may reveal who borrowed the map last. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Resolution\n**Meaning:** The outcome or settlement of an important conflict.\n**In practice:** The club eventually discovers the cause of the damage. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Chronology: The order in which events actually occur in story time","Flashback: A shift in narration to an earlier event","Foreshadowing: A clue or suggestion that prepares the reader for a later event","Suspense: Uncertainty about an outcome sustains reader interest","Resolution: The outcome or settlement of an important conflict"],"cards":[{"front":"What does \"Chronology\" mean in literary study?","back":"The order in which events actually occur in story time. Example: Friday''s loan happened before Tuesday''s discovery.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Flashback\" mean in literary study?","back":"A shift in narration to an earlier event. Example: The chapter returns from Tuesday to the previous Friday.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Foreshadowing\" mean in literary study?","back":"A clue or suggestion that prepares the reader for a later event. Example: A warning about fragile maps hints at a later problem.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Suspense\" mean in literary study?","back":"Uncertainty about an outcome sustains reader interest. Example: The register may reveal who borrowed the map last.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Resolution\" mean in literary study?","back":"The outcome or settlement of an important conflict. Example: The club eventually discovers the cause of the damage.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate plot sequence and flashback?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Plot Sequence and Flashback\", which literary concept matches this definition: The order in which events actually occur in story time?","options":[{"id":"A","text":"Flashback"},{"id":"B","text":"Chronology"},{"id":"C","text":"Foreshadowing"},{"id":"D","text":"Suspense"}],"answer":"B","explanation":"Chronology is the correct concept because The order in which events actually occur in story time. The model example is: Friday''s loan happened before Tuesday''s discovery. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Plot Sequence and Flashback\": Friday''s loan happened before Tuesday''s discovery?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Flashback"},{"id":"C","text":"Foreshadowing"},{"id":"D","text":"Suspense"}],"answer":"A","explanation":"The example illustrates Chronology: The order in which events actually occur in story time. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Plot Sequence and Flashback\", which literary concept matches this definition: A shift in narration to an earlier event?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Foreshadowing"},{"id":"C","text":"Suspense"},{"id":"D","text":"Flashback"}],"answer":"D","explanation":"Flashback is the correct concept because A shift in narration to an earlier event. The model example is: The chapter returns from Tuesday to the previous Friday. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Plot Sequence and Flashback\": The chapter returns from Tuesday to the previous Friday?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Foreshadowing"},{"id":"C","text":"Flashback"},{"id":"D","text":"Suspense"}],"answer":"C","explanation":"The example illustrates Flashback: A shift in narration to an earlier event. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Plot Sequence and Flashback\", which literary concept matches this definition: A clue or suggestion that prepares the reader for a later event?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Foreshadowing"},{"id":"C","text":"Flashback"},{"id":"D","text":"Suspense"}],"answer":"B","explanation":"Foreshadowing is the correct concept because A clue or suggestion that prepares the reader for a later event. The model example is: A warning about fragile maps hints at a later problem. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Plot Sequence and Flashback\": A warning about fragile maps hints at a later problem?","options":[{"id":"A","text":"Foreshadowing"},{"id":"B","text":"Chronology"},{"id":"C","text":"Flashback"},{"id":"D","text":"Suspense"}],"answer":"A","explanation":"The example illustrates Foreshadowing: A clue or suggestion that prepares the reader for a later event. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Plot Sequence and Flashback\", which literary concept matches this definition: Uncertainty about an outcome sustains reader interest?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Flashback"},{"id":"C","text":"Foreshadowing"},{"id":"D","text":"Suspense"}],"answer":"D","explanation":"Suspense is the correct concept because Uncertainty about an outcome sustains reader interest. The model example is: The register may reveal who borrowed the map last. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Plot Sequence and Flashback\": The register may reveal who borrowed the map last?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Flashback"},{"id":"C","text":"Suspense"},{"id":"D","text":"Foreshadowing"}],"answer":"C","explanation":"The example illustrates Suspense: Uncertainty about an outcome sustains reader interest. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Plot Sequence and Flashback\", which literary concept matches this definition: The outcome or settlement of an important conflict?","options":[{"id":"A","text":"Chronology"},{"id":"B","text":"Resolution"},{"id":"C","text":"Flashback"},{"id":"D","text":"Foreshadowing"}],"answer":"B","explanation":"Resolution is the correct concept because The outcome or settlement of an important conflict. The model example is: The club eventually discovers the cause of the damage. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Plot Sequence and Flashback\": The club eventually discovers the cause of the damage?","options":[{"id":"A","text":"Resolution"},{"id":"B","text":"Chronology"},{"id":"C","text":"Flashback"},{"id":"D","text":"Foreshadowing"}],"answer":"A","explanation":"The example illustrates Resolution: The outcome or settlement of an important conflict. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS1","term":3,"seq":5,"name":"Building Evidence-Based Literature Essays","slug":"lit-sss1-t3-building-evidence-based-literature-essays","code":"G26LITSSS1T3U5","body":"# Building Evidence-Based Literature Essays — SSS1 Literature in English, Third Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nA literary paragraph should make an arguable claim, support it with a precise detail and explain how the detail leads to meaning. Short quotations matter more than long retellings; avoid inventing lines from prescribed books.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Original passage: ''Kemi saw the queue outside the clinic and surrendered her place to an older man. Nobody praised her; she simply moved to the back and unfolded her book again.''\n\n## A worked close reading\nClaim: Kemi is presented as considerate. Evidence: she gives up her position without public reward. Reasoning: the absence of praise makes the gesture appear motivated by concern rather than applause. This is an inference; it should be expressed with suitable restraint.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Interpretive claim\n**Meaning:** A reasoned argument about how a text creates meaning.\n**In practice:** Kemi''s quiet action suggests consideration. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Evidence\n**Meaning:** A precise detail from a passage that supports a claim.\n**In practice:** She gives her place to an older man. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Commentary\n**Meaning:** Explanation connecting quoted detail to the main idea.\n**In practice:** The lack of praise strengthens the reading of unselfishness. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Counterreading\n**Meaning:** A plausible alternative interpretation to assess fairly.\n**In practice:** Kemi might also have simply had more time to wait. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Conclusion\n**Meaning:** A final synthesis of the demonstrated argument.\n**In practice:** The choices together present consideration while leaving motive partly open. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Interpretive claim: A reasoned argument about how a text creates meaning","Evidence: A precise detail from a passage that supports a claim","Commentary: Explanation connecting quoted detail to the main idea","Counterreading: A plausible alternative interpretation to assess fairly","Conclusion: A final synthesis of the demonstrated argument"],"cards":[{"front":"What does \"Interpretive claim\" mean in literary study?","back":"A reasoned argument about how a text creates meaning. Example: Kemi''s quiet action suggests consideration.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Evidence\" mean in literary study?","back":"A precise detail from a passage that supports a claim. Example: She gives her place to an older man.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Commentary\" mean in literary study?","back":"Explanation connecting quoted detail to the main idea. Example: The lack of praise strengthens the reading of unselfishness.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Counterreading\" mean in literary study?","back":"A plausible alternative interpretation to assess fairly. Example: Kemi might also have simply had more time to wait.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Conclusion\" mean in literary study?","back":"A final synthesis of the demonstrated argument. Example: The choices together present consideration while leaving motive partly open.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate building evidence-based literature essays?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS1 lesson \"Building Evidence-Based Literature Essays\", which literary concept matches this definition: A reasoned argument about how a text creates meaning?","options":[{"id":"A","text":"Evidence"},{"id":"B","text":"Commentary"},{"id":"C","text":"Counterreading"},{"id":"D","text":"Interpretive claim"}],"answer":"D","explanation":"Interpretive claim is the correct concept because A reasoned argument about how a text creates meaning. The model example is: Kemi''s quiet action suggests consideration. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Building Evidence-Based Literature Essays\": Kemi''s quiet action suggests consideration?","options":[{"id":"A","text":"Evidence"},{"id":"B","text":"Commentary"},{"id":"C","text":"Interpretive claim"},{"id":"D","text":"Counterreading"}],"answer":"C","explanation":"The example illustrates Interpretive claim: A reasoned argument about how a text creates meaning. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Building Evidence-Based Literature Essays\", which literary concept matches this definition: A precise detail from a passage that supports a claim?","options":[{"id":"A","text":"Interpretive claim"},{"id":"B","text":"Evidence"},{"id":"C","text":"Commentary"},{"id":"D","text":"Counterreading"}],"answer":"B","explanation":"Evidence is the correct concept because A precise detail from a passage that supports a claim. The model example is: She gives her place to an older man. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Building Evidence-Based Literature Essays\": She gives her place to an older man?","options":[{"id":"A","text":"Evidence"},{"id":"B","text":"Interpretive claim"},{"id":"C","text":"Commentary"},{"id":"D","text":"Counterreading"}],"answer":"A","explanation":"The example illustrates Evidence: A precise detail from a passage that supports a claim. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Building Evidence-Based Literature Essays\", which literary concept matches this definition: Explanation connecting quoted detail to the main idea?","options":[{"id":"A","text":"Interpretive claim"},{"id":"B","text":"Evidence"},{"id":"C","text":"Counterreading"},{"id":"D","text":"Commentary"}],"answer":"D","explanation":"Commentary is the correct concept because Explanation connecting quoted detail to the main idea. The model example is: The lack of praise strengthens the reading of unselfishness. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Building Evidence-Based Literature Essays\": The lack of praise strengthens the reading of unselfishness?","options":[{"id":"A","text":"Interpretive claim"},{"id":"B","text":"Evidence"},{"id":"C","text":"Commentary"},{"id":"D","text":"Counterreading"}],"answer":"C","explanation":"The example illustrates Commentary: Explanation connecting quoted detail to the main idea. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Building Evidence-Based Literature Essays\", which literary concept matches this definition: A plausible alternative interpretation to assess fairly?","options":[{"id":"A","text":"Interpretive claim"},{"id":"B","text":"Counterreading"},{"id":"C","text":"Evidence"},{"id":"D","text":"Commentary"}],"answer":"B","explanation":"Counterreading is the correct concept because A plausible alternative interpretation to assess fairly. The model example is: Kemi might also have simply had more time to wait. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Building Evidence-Based Literature Essays\": Kemi might also have simply had more time to wait?","options":[{"id":"A","text":"Counterreading"},{"id":"B","text":"Interpretive claim"},{"id":"C","text":"Evidence"},{"id":"D","text":"Commentary"}],"answer":"A","explanation":"The example illustrates Counterreading: A plausible alternative interpretation to assess fairly. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS1 lesson \"Building Evidence-Based Literature Essays\", which literary concept matches this definition: A final synthesis of the demonstrated argument?","options":[{"id":"A","text":"Interpretive claim"},{"id":"B","text":"Evidence"},{"id":"C","text":"Commentary"},{"id":"D","text":"Conclusion"}],"answer":"D","explanation":"Conclusion is the correct concept because A final synthesis of the demonstrated argument. The model example is: The choices together present consideration while leaving motive partly open. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Building Evidence-Based Literature Essays\": The choices together present consideration while leaving motive partly open?","options":[{"id":"A","text":"Interpretive claim"},{"id":"B","text":"Evidence"},{"id":"C","text":"Conclusion"},{"id":"D","text":"Commentary"}],"answer":"C","explanation":"The example illustrates Conclusion: A final synthesis of the demonstrated argument. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":1,"seq":1,"name":"African Poetry and Context","slug":"lit-sss2-t1-african-poetry-and-context","code":"G26LITSSS2T1U1","body":"# African Poetry and Context — SSS2 Literature in English, First Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nContext can illuminate a poem, but it should never replace attentive reading. Social history, language and performance traditions may shape literary images; avoid treating African poetry as one uniform tradition or attributing invented lines to real poets.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Original poem: ''The market drum remembered rain; / The river kept the names of trees. / Between the stalls an old man said, / Our stories travel with the breeze.''\n\n## A worked close reading\nThe market, drum and river build a network of remembered place. Personification gives inanimate features a conserving role, while ''our stories'' foregrounds collective memory. The four lines are original teaching material, not a quotation from a published African poem.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Cultural context\n**Meaning:** Relevant shared practices histories or values surrounding a text.\n**In practice:** The market drum may evoke communal performance. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Collective memory\n**Meaning:** A community''s ways of remembering events and experience.\n**In practice:** Our stories travel beyond the market. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Personification\n**Meaning:** A nonhuman object receives a human capacity or action.\n**In practice:** The river keeps the names of trees. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Speaker\n**Meaning:** The voice heard in the poem whether or not it is the poet.\n**In practice:** The old man''s words are reported by the poetic voice. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Close reading\n**Meaning:** Attention to exact diction structure and images before broad claims.\n**In practice:** The words remembered and kept both suggest preservation. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Cultural context: Relevant shared practices histories or values surrounding a text","Collective memory: A community''s ways of remembering events and experience","Personification: A nonhuman object receives a human capacity or action","Speaker: The voice heard in the poem whether or not it is the poet","Close reading: Attention to exact diction structure and images before broad claims"],"cards":[{"front":"What does \"Cultural context\" mean in literary study?","back":"Relevant shared practices histories or values surrounding a text. Example: The market drum may evoke communal performance.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Collective memory\" mean in literary study?","back":"A community''s ways of remembering events and experience. Example: Our stories travel beyond the market.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Personification\" mean in literary study?","back":"A nonhuman object receives a human capacity or action. Example: The river keeps the names of trees.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Speaker\" mean in literary study?","back":"The voice heard in the poem whether or not it is the poet. Example: The old man''s words are reported by the poetic voice.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Close reading\" mean in literary study?","back":"Attention to exact diction structure and images before broad claims. Example: The words remembered and kept both suggest preservation.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate african poetry and context?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"African Poetry and Context\", which literary concept matches this definition: Relevant shared practices histories or values surrounding a text?","options":[{"id":"A","text":"Collective memory"},{"id":"B","text":"Cultural context"},{"id":"C","text":"Personification"},{"id":"D","text":"Speaker"}],"answer":"B","explanation":"Cultural context is the correct concept because Relevant shared practices histories or values surrounding a text. The model example is: The market drum may evoke communal performance. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"African Poetry and Context\": The market drum may evoke communal performance?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Collective memory"},{"id":"C","text":"Personification"},{"id":"D","text":"Speaker"}],"answer":"A","explanation":"The example illustrates Cultural context: Relevant shared practices histories or values surrounding a text. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"African Poetry and Context\", which literary concept matches this definition: A community''s ways of remembering events and experience?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Personification"},{"id":"C","text":"Speaker"},{"id":"D","text":"Collective memory"}],"answer":"D","explanation":"Collective memory is the correct concept because A community''s ways of remembering events and experience. The model example is: Our stories travel beyond the market. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"African Poetry and Context\": Our stories travel beyond the market?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Personification"},{"id":"C","text":"Collective memory"},{"id":"D","text":"Speaker"}],"answer":"C","explanation":"The example illustrates Collective memory: A community''s ways of remembering events and experience. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"African Poetry and Context\", which literary concept matches this definition: A nonhuman object receives a human capacity or action?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Personification"},{"id":"C","text":"Collective memory"},{"id":"D","text":"Speaker"}],"answer":"B","explanation":"Personification is the correct concept because A nonhuman object receives a human capacity or action. The model example is: The river keeps the names of trees. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"African Poetry and Context\": The river keeps the names of trees?","options":[{"id":"A","text":"Personification"},{"id":"B","text":"Cultural context"},{"id":"C","text":"Collective memory"},{"id":"D","text":"Speaker"}],"answer":"A","explanation":"The example illustrates Personification: A nonhuman object receives a human capacity or action. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"African Poetry and Context\", which literary concept matches this definition: The voice heard in the poem whether or not it is the poet?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Collective memory"},{"id":"C","text":"Personification"},{"id":"D","text":"Speaker"}],"answer":"D","explanation":"Speaker is the correct concept because The voice heard in the poem whether or not it is the poet. The model example is: The old man''s words are reported by the poetic voice. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"African Poetry and Context\": The old man''s words are reported by the poetic voice?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Collective memory"},{"id":"C","text":"Speaker"},{"id":"D","text":"Personification"}],"answer":"C","explanation":"The example illustrates Speaker: The voice heard in the poem whether or not it is the poet. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"African Poetry and Context\", which literary concept matches this definition: Attention to exact diction structure and images before broad claims?","options":[{"id":"A","text":"Cultural context"},{"id":"B","text":"Close reading"},{"id":"C","text":"Collective memory"},{"id":"D","text":"Personification"}],"answer":"B","explanation":"Close reading is the correct concept because Attention to exact diction structure and images before broad claims. The model example is: The words remembered and kept both suggest preservation. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"African Poetry and Context\": The words remembered and kept both suggest preservation?","options":[{"id":"A","text":"Close reading"},{"id":"B","text":"Cultural context"},{"id":"C","text":"Collective memory"},{"id":"D","text":"Personification"}],"answer":"A","explanation":"The example illustrates Close reading: Attention to exact diction structure and images before broad claims. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":1,"seq":2,"name":"Poetic Persona and Perspective","slug":"lit-sss2-t1-poetic-persona-and-perspective","code":"G26LITSSS2T1U2","body":"# Poetic Persona and Perspective — SSS2 Literature in English, First Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nAdvanced appreciation asks who speaks, what the speaker knows, and what the poem withholds. A dramatic persona may contradict another voice. Distinguish the writer''s artistic creation from biographical facts that have not been documented.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> I am the watchman of the empty pier. By day I say the harbour is safe; at night I hear loose ropes strike the boats. When visitors ask about storms, I point to the bright horizon and do not mention the warnings posted behind the gate.\n\n## A worked close reading\nThe invented watchman voice reveals a gap between public reassurance and private knowledge. The contrast supports a reading of concealment; it does not establish whether the watchman intends harm.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Persona\n**Meaning:** An assumed speaking identity within a poem.\n**In practice:** A watchman narrates his fears in the first person. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Perspective\n**Meaning:** The speaker''s limited position and interpretation of events.\n**In practice:** The watchman knows about ropes and notices more than visitors. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Address\n**Meaning:** The listener or imagined audience to whom speech is directed.\n**In practice:** The watchman answers visitors at the pier. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Dramatic irony\n**Meaning:** The audience knows something a character within the scene does not.\n**In practice:** Readers know the warnings that arriving visitors have not seen. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Ambiguity\n**Meaning:** Wording or circumstances allow more than one defensible meaning.\n**In practice:** The watchman''s motive for silence is not established. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Persona: An assumed speaking identity within a poem","Perspective: The speaker''s limited position and interpretation of events","Address: The listener or imagined audience to whom speech is directed","Dramatic irony: The audience knows something a character within the scene does not","Ambiguity: Wording or circumstances allow more than one defensible meaning"],"cards":[{"front":"What does \"Persona\" mean in literary study?","back":"An assumed speaking identity within a poem. Example: A watchman narrates his fears in the first person.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Perspective\" mean in literary study?","back":"The speaker''s limited position and interpretation of events. Example: The watchman knows about ropes and notices more than visitors.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Address\" mean in literary study?","back":"The listener or imagined audience to whom speech is directed. Example: The watchman answers visitors at the pier.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Dramatic irony\" mean in literary study?","back":"The audience knows something a character within the scene does not. Example: Readers know the warnings that arriving visitors have not seen.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Ambiguity\" mean in literary study?","back":"Wording or circumstances allow more than one defensible meaning. Example: The watchman''s motive for silence is not established.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate poetic persona and perspective?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Poetic Persona and Perspective\", which literary concept matches this definition: An assumed speaking identity within a poem?","options":[{"id":"A","text":"Perspective"},{"id":"B","text":"Address"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Persona"}],"answer":"D","explanation":"Persona is the correct concept because An assumed speaking identity within a poem. The model example is: A watchman narrates his fears in the first person. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Persona and Perspective\": A watchman narrates his fears in the first person?","options":[{"id":"A","text":"Perspective"},{"id":"B","text":"Address"},{"id":"C","text":"Persona"},{"id":"D","text":"Dramatic irony"}],"answer":"C","explanation":"The example illustrates Persona: An assumed speaking identity within a poem. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Persona and Perspective\", which literary concept matches this definition: The speaker''s limited position and interpretation of events?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Perspective"},{"id":"C","text":"Address"},{"id":"D","text":"Dramatic irony"}],"answer":"B","explanation":"Perspective is the correct concept because The speaker''s limited position and interpretation of events. The model example is: The watchman knows about ropes and notices more than visitors. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Persona and Perspective\": The watchman knows about ropes and notices more than visitors?","options":[{"id":"A","text":"Perspective"},{"id":"B","text":"Persona"},{"id":"C","text":"Address"},{"id":"D","text":"Dramatic irony"}],"answer":"A","explanation":"The example illustrates Perspective: The speaker''s limited position and interpretation of events. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Persona and Perspective\", which literary concept matches this definition: The listener or imagined audience to whom speech is directed?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Perspective"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Address"}],"answer":"D","explanation":"Address is the correct concept because The listener or imagined audience to whom speech is directed. The model example is: The watchman answers visitors at the pier. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Persona and Perspective\": The watchman answers visitors at the pier?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Perspective"},{"id":"C","text":"Address"},{"id":"D","text":"Dramatic irony"}],"answer":"C","explanation":"The example illustrates Address: The listener or imagined audience to whom speech is directed. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Persona and Perspective\", which literary concept matches this definition: The audience knows something a character within the scene does not?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Dramatic irony"},{"id":"C","text":"Perspective"},{"id":"D","text":"Address"}],"answer":"B","explanation":"Dramatic irony is the correct concept because The audience knows something a character within the scene does not. The model example is: Readers know the warnings that arriving visitors have not seen. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Persona and Perspective\": Readers know the warnings that arriving visitors have not seen?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Persona"},{"id":"C","text":"Perspective"},{"id":"D","text":"Address"}],"answer":"A","explanation":"The example illustrates Dramatic irony: The audience knows something a character within the scene does not. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Persona and Perspective\", which literary concept matches this definition: Wording or circumstances allow more than one defensible meaning?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Perspective"},{"id":"C","text":"Address"},{"id":"D","text":"Ambiguity"}],"answer":"D","explanation":"Ambiguity is the correct concept because Wording or circumstances allow more than one defensible meaning. The model example is: The watchman''s motive for silence is not established. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Persona and Perspective\": The watchman''s motive for silence is not established?","options":[{"id":"A","text":"Persona"},{"id":"B","text":"Perspective"},{"id":"C","text":"Ambiguity"},{"id":"D","text":"Address"}],"answer":"C","explanation":"The example illustrates Ambiguity: Wording or circumstances allow more than one defensible meaning. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":1,"seq":3,"name":"Symbols and Layered Meaning","slug":"lit-sss2-t1-symbols-and-layered-meaning","code":"G26LITSSS2T1U3","body":"# Symbols and Layered Meaning — SSS2 Literature in English, First Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nSymbols carry meaning by accumulating significance within a literary work. A tree or key is not universally freedom or imprisonment; interpretation depends on repeated context, character response and consequences.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> The classroom window was always locked until the science teacher handed the key to the students. By term''s end the window stood open, though the heat remained. During the farewell speech one student thanked the teacher for trusting them.\n\n## A worked close reading\nThe key is literally used to unlock a window. It may also symbolise shared responsibility because control changes hands. Heat remaining prevents an exaggerated claim that every problem is solved.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Symbol\n**Meaning:** A concrete element develops significance beyond its literal function.\n**In practice:** The transferred key can suggest entrusted responsibility. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Motif\n**Meaning:** A repeated image action or idea helps build a theme.\n**In practice:** The open window recurs whenever students make decisions. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Connotation\n**Meaning:** An association carried by a word beyond its dictionary sense.\n**In practice:** Open may suggest possibility in this context. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Literal meaning\n**Meaning:** The immediate practical sense of a word or event.\n**In practice:** The key physically opens the window. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Ambiguity\n**Meaning:** A detail sustains more than one supported interpretation.\n**In practice:** An open window might imply trust but also physical discomfort. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Symbol: A concrete element develops significance beyond its literal function","Motif: A repeated image action or idea helps build a theme","Connotation: An association carried by a word beyond its dictionary sense","Literal meaning: The immediate practical sense of a word or event","Ambiguity: A detail sustains more than one supported interpretation"],"cards":[{"front":"What does \"Symbol\" mean in literary study?","back":"A concrete element develops significance beyond its literal function. Example: The transferred key can suggest entrusted responsibility.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Motif\" mean in literary study?","back":"A repeated image action or idea helps build a theme. Example: The open window recurs whenever students make decisions.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Connotation\" mean in literary study?","back":"An association carried by a word beyond its dictionary sense. Example: Open may suggest possibility in this context.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Literal meaning\" mean in literary study?","back":"The immediate practical sense of a word or event. Example: The key physically opens the window.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Ambiguity\" mean in literary study?","back":"A detail sustains more than one supported interpretation. Example: An open window might imply trust but also physical discomfort.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate symbols and layered meaning?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Symbols and Layered Meaning\", which literary concept matches this definition: A concrete element develops significance beyond its literal function?","options":[{"id":"A","text":"Motif"},{"id":"B","text":"Symbol"},{"id":"C","text":"Connotation"},{"id":"D","text":"Literal meaning"}],"answer":"B","explanation":"Symbol is the correct concept because A concrete element develops significance beyond its literal function. The model example is: The transferred key can suggest entrusted responsibility. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Symbols and Layered Meaning\": The transferred key can suggest entrusted responsibility?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Motif"},{"id":"C","text":"Connotation"},{"id":"D","text":"Literal meaning"}],"answer":"A","explanation":"The example illustrates Symbol: A concrete element develops significance beyond its literal function. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Symbols and Layered Meaning\", which literary concept matches this definition: A repeated image action or idea helps build a theme?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Connotation"},{"id":"C","text":"Literal meaning"},{"id":"D","text":"Motif"}],"answer":"D","explanation":"Motif is the correct concept because A repeated image action or idea helps build a theme. The model example is: The open window recurs whenever students make decisions. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Symbols and Layered Meaning\": The open window recurs whenever students make decisions?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Connotation"},{"id":"C","text":"Motif"},{"id":"D","text":"Literal meaning"}],"answer":"C","explanation":"The example illustrates Motif: A repeated image action or idea helps build a theme. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Symbols and Layered Meaning\", which literary concept matches this definition: An association carried by a word beyond its dictionary sense?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Connotation"},{"id":"C","text":"Motif"},{"id":"D","text":"Literal meaning"}],"answer":"B","explanation":"Connotation is the correct concept because An association carried by a word beyond its dictionary sense. The model example is: Open may suggest possibility in this context. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Symbols and Layered Meaning\": Open may suggest possibility in this context?","options":[{"id":"A","text":"Connotation"},{"id":"B","text":"Symbol"},{"id":"C","text":"Motif"},{"id":"D","text":"Literal meaning"}],"answer":"A","explanation":"The example illustrates Connotation: An association carried by a word beyond its dictionary sense. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Symbols and Layered Meaning\", which literary concept matches this definition: The immediate practical sense of a word or event?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Motif"},{"id":"C","text":"Connotation"},{"id":"D","text":"Literal meaning"}],"answer":"D","explanation":"Literal meaning is the correct concept because The immediate practical sense of a word or event. The model example is: The key physically opens the window. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Symbols and Layered Meaning\": The key physically opens the window?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Motif"},{"id":"C","text":"Literal meaning"},{"id":"D","text":"Connotation"}],"answer":"C","explanation":"The example illustrates Literal meaning: The immediate practical sense of a word or event. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Symbols and Layered Meaning\", which literary concept matches this definition: A detail sustains more than one supported interpretation?","options":[{"id":"A","text":"Symbol"},{"id":"B","text":"Ambiguity"},{"id":"C","text":"Motif"},{"id":"D","text":"Connotation"}],"answer":"B","explanation":"Ambiguity is the correct concept because A detail sustains more than one supported interpretation. The model example is: An open window might imply trust but also physical discomfort. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Symbols and Layered Meaning\": An open window might imply trust but also physical discomfort?","options":[{"id":"A","text":"Ambiguity"},{"id":"B","text":"Symbol"},{"id":"C","text":"Motif"},{"id":"D","text":"Connotation"}],"answer":"A","explanation":"The example illustrates Ambiguity: A detail sustains more than one supported interpretation. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":1,"seq":4,"name":"Comparing Poetic Interpretations","slug":"lit-sss2-t1-comparing-poetic-interpretations","code":"G26LITSSS2T1U4","body":"# Comparing Poetic Interpretations — SSS2 Literature in English, First Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nComparison should establish a shared question and examine how each text approaches it differently. Avoid parallel plot summaries. Begin with a point of similarity, then compare diction, imagery, tone and the strength of evidence.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Poem A: ''The lamps woke early on the hill; / My footsteps slowed against the night.'' Poem B: ''The gates stayed shut beneath the sun; / I counted hours until the rain.''\n\n## A worked close reading\nBoth speakers face obstacles. A''s dark hill and slowing steps suggest fatigue or caution; B''s closed gate implies exclusion or delay even in daylight. The poems contrast darkness with sunlight, but neither image is automatically good or bad.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Comparison point\n**Meaning:** A shared question or feature examined across texts.\n**In practice:** Both speakers encounter a barrier. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Contrast\n**Meaning:** A meaningful difference in technique or implication.\n**In practice:** One poem uses darkness while the other uses locked gates in sunlight. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Close quotation\n**Meaning:** A short exact extract that substantiates an interpretation.\n**In practice:** My footsteps slowed provides evidence of hesitation. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Evaluative language\n**Meaning:** Wording judging the significance of a literary choice.\n**In practice:** The gate offers a more explicit social obstacle than the hill. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Balanced interpretation\n**Meaning:** A reading which acknowledges evidence and limits.\n**In practice:** Neither passage proves the speaker''s final destination. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Comparison point: A shared question or feature examined across texts","Contrast: A meaningful difference in technique or implication","Close quotation: A short exact extract that substantiates an interpretation","Evaluative language: Wording judging the significance of a literary choice","Balanced interpretation: A reading which acknowledges evidence and limits"],"cards":[{"front":"What does \"Comparison point\" mean in literary study?","back":"A shared question or feature examined across texts. Example: Both speakers encounter a barrier.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Contrast\" mean in literary study?","back":"A meaningful difference in technique or implication. Example: One poem uses darkness while the other uses locked gates in sunlight.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Close quotation\" mean in literary study?","back":"A short exact extract that substantiates an interpretation. Example: My footsteps slowed provides evidence of hesitation.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Evaluative language\" mean in literary study?","back":"Wording judging the significance of a literary choice. Example: The gate offers a more explicit social obstacle than the hill.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Balanced interpretation\" mean in literary study?","back":"A reading which acknowledges evidence and limits. Example: Neither passage proves the speaker''s final destination.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate comparing poetic interpretations?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Comparing Poetic Interpretations\", which literary concept matches this definition: A shared question or feature examined across texts?","options":[{"id":"A","text":"Contrast"},{"id":"B","text":"Close quotation"},{"id":"C","text":"Evaluative language"},{"id":"D","text":"Comparison point"}],"answer":"D","explanation":"Comparison point is the correct concept because A shared question or feature examined across texts. The model example is: Both speakers encounter a barrier. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Comparing Poetic Interpretations\": Both speakers encounter a barrier?","options":[{"id":"A","text":"Contrast"},{"id":"B","text":"Close quotation"},{"id":"C","text":"Comparison point"},{"id":"D","text":"Evaluative language"}],"answer":"C","explanation":"The example illustrates Comparison point: A shared question or feature examined across texts. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Comparing Poetic Interpretations\", which literary concept matches this definition: A meaningful difference in technique or implication?","options":[{"id":"A","text":"Comparison point"},{"id":"B","text":"Contrast"},{"id":"C","text":"Close quotation"},{"id":"D","text":"Evaluative language"}],"answer":"B","explanation":"Contrast is the correct concept because A meaningful difference in technique or implication. The model example is: One poem uses darkness while the other uses locked gates in sunlight. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Comparing Poetic Interpretations\": One poem uses darkness while the other uses locked gates in sunlight?","options":[{"id":"A","text":"Contrast"},{"id":"B","text":"Comparison point"},{"id":"C","text":"Close quotation"},{"id":"D","text":"Evaluative language"}],"answer":"A","explanation":"The example illustrates Contrast: A meaningful difference in technique or implication. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Comparing Poetic Interpretations\", which literary concept matches this definition: A short exact extract that substantiates an interpretation?","options":[{"id":"A","text":"Comparison point"},{"id":"B","text":"Contrast"},{"id":"C","text":"Evaluative language"},{"id":"D","text":"Close quotation"}],"answer":"D","explanation":"Close quotation is the correct concept because A short exact extract that substantiates an interpretation. The model example is: My footsteps slowed provides evidence of hesitation. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Comparing Poetic Interpretations\": My footsteps slowed provides evidence of hesitation?","options":[{"id":"A","text":"Comparison point"},{"id":"B","text":"Contrast"},{"id":"C","text":"Close quotation"},{"id":"D","text":"Evaluative language"}],"answer":"C","explanation":"The example illustrates Close quotation: A short exact extract that substantiates an interpretation. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Comparing Poetic Interpretations\", which literary concept matches this definition: Wording judging the significance of a literary choice?","options":[{"id":"A","text":"Comparison point"},{"id":"B","text":"Evaluative language"},{"id":"C","text":"Contrast"},{"id":"D","text":"Close quotation"}],"answer":"B","explanation":"Evaluative language is the correct concept because Wording judging the significance of a literary choice. The model example is: The gate offers a more explicit social obstacle than the hill. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Comparing Poetic Interpretations\": The gate offers a more explicit social obstacle than the hill?","options":[{"id":"A","text":"Evaluative language"},{"id":"B","text":"Comparison point"},{"id":"C","text":"Contrast"},{"id":"D","text":"Close quotation"}],"answer":"A","explanation":"The example illustrates Evaluative language: Wording judging the significance of a literary choice. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Comparing Poetic Interpretations\", which literary concept matches this definition: A reading which acknowledges evidence and limits?","options":[{"id":"A","text":"Comparison point"},{"id":"B","text":"Contrast"},{"id":"C","text":"Close quotation"},{"id":"D","text":"Balanced interpretation"}],"answer":"D","explanation":"Balanced interpretation is the correct concept because A reading which acknowledges evidence and limits. The model example is: Neither passage proves the speaker''s final destination. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Comparing Poetic Interpretations\": Neither passage proves the speaker''s final destination?","options":[{"id":"A","text":"Comparison point"},{"id":"B","text":"Contrast"},{"id":"C","text":"Balanced interpretation"},{"id":"D","text":"Close quotation"}],"answer":"C","explanation":"The example illustrates Balanced interpretation: A reading which acknowledges evidence and limits. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":1,"seq":5,"name":"Poetic Sound and Rhythm","slug":"lit-sss2-t1-poetic-sound-and-rhythm","code":"G26LITSSS2T1U5","body":"# Poetic Sound and Rhythm — SSS2 Literature in English, First Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nSound contributes to movement, pace and emphasis in verse. Identify actual repeated phonemes before naming alliteration or assonance; spelling alone can be misleading. Poetry can be rhythmic without rhyming at line ends.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> The slow boats slid toward the shore. / A hollow horn called through the fog. / We waited, waited, then the oars / Broke water like a sudden knock.\n\n## A worked close reading\nThe repeated beginning /s/ sounds build flowing movement in the opening; repetition of ''waited'' stretches the sense of delay. The simile at the end introduces an abrupt sound. A good answer explains the effect rather than counting devices.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Alliteration\n**Meaning:** Nearby words repeat beginning consonant sounds.\n**In practice:** Slow boats slid repeats s at the beginnings of prominent words. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Assonance\n**Meaning:** Nearby words repeat vowel sounds in a sound pattern.\n**In practice:** Low boats roll home echoes long o vowel sounds. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Repetition\n**Meaning:** Deliberate reuse of wording builds rhythm or emphasis.\n**In practice:** We waited waited makes the delay felt. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Enjambment\n**Meaning:** A sentence or idea continues across a line break without full stop.\n**In practice:** The phrase about the oars continues into the final line. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. End-stop\n**Meaning:** Punctuation or syntactic completion gives a line a definite pause.\n**In practice:** The first line ends with a full stop after shore. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Alliteration: Nearby words repeat beginning consonant sounds","Assonance: Nearby words repeat vowel sounds in a sound pattern","Repetition: Deliberate reuse of wording builds rhythm or emphasis","Enjambment: A sentence or idea continues across a line break without full stop","End-stop: Punctuation or syntactic completion gives a line a definite pause"],"cards":[{"front":"What does \"Alliteration\" mean in literary study?","back":"Nearby words repeat beginning consonant sounds. Example: Slow boats slid repeats s at the beginnings of prominent words.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Assonance\" mean in literary study?","back":"Nearby words repeat vowel sounds in a sound pattern. Example: Low boats roll home echoes long o vowel sounds.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Repetition\" mean in literary study?","back":"Deliberate reuse of wording builds rhythm or emphasis. Example: We waited waited makes the delay felt.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Enjambment\" mean in literary study?","back":"A sentence or idea continues across a line break without full stop. Example: The phrase about the oars continues into the final line.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"End-stop\" mean in literary study?","back":"Punctuation or syntactic completion gives a line a definite pause. Example: The first line ends with a full stop after shore.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate poetic sound and rhythm?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Poetic Sound and Rhythm\", which literary concept matches this definition: Nearby words repeat beginning consonant sounds?","options":[{"id":"A","text":"Assonance"},{"id":"B","text":"Alliteration"},{"id":"C","text":"Repetition"},{"id":"D","text":"Enjambment"}],"answer":"B","explanation":"Alliteration is the correct concept because Nearby words repeat beginning consonant sounds. The model example is: Slow boats slid repeats s at the beginnings of prominent words. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Sound and Rhythm\": Slow boats slid repeats s at the beginnings of prominent words?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Assonance"},{"id":"C","text":"Repetition"},{"id":"D","text":"Enjambment"}],"answer":"A","explanation":"The example illustrates Alliteration: Nearby words repeat beginning consonant sounds. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Sound and Rhythm\", which literary concept matches this definition: Nearby words repeat vowel sounds in a sound pattern?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Repetition"},{"id":"C","text":"Enjambment"},{"id":"D","text":"Assonance"}],"answer":"D","explanation":"Assonance is the correct concept because Nearby words repeat vowel sounds in a sound pattern. The model example is: Low boats roll home echoes long o vowel sounds. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Sound and Rhythm\": Low boats roll home echoes long o vowel sounds?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Repetition"},{"id":"C","text":"Assonance"},{"id":"D","text":"Enjambment"}],"answer":"C","explanation":"The example illustrates Assonance: Nearby words repeat vowel sounds in a sound pattern. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Sound and Rhythm\", which literary concept matches this definition: Deliberate reuse of wording builds rhythm or emphasis?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Repetition"},{"id":"C","text":"Assonance"},{"id":"D","text":"Enjambment"}],"answer":"B","explanation":"Repetition is the correct concept because Deliberate reuse of wording builds rhythm or emphasis. The model example is: We waited waited makes the delay felt. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Sound and Rhythm\": We waited waited makes the delay felt?","options":[{"id":"A","text":"Repetition"},{"id":"B","text":"Alliteration"},{"id":"C","text":"Assonance"},{"id":"D","text":"Enjambment"}],"answer":"A","explanation":"The example illustrates Repetition: Deliberate reuse of wording builds rhythm or emphasis. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Sound and Rhythm\", which literary concept matches this definition: A sentence or idea continues across a line break without full stop?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Assonance"},{"id":"C","text":"Repetition"},{"id":"D","text":"Enjambment"}],"answer":"D","explanation":"Enjambment is the correct concept because A sentence or idea continues across a line break without full stop. The model example is: The phrase about the oars continues into the final line. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Sound and Rhythm\": The phrase about the oars continues into the final line?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Assonance"},{"id":"C","text":"Enjambment"},{"id":"D","text":"Repetition"}],"answer":"C","explanation":"The example illustrates Enjambment: A sentence or idea continues across a line break without full stop. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Poetic Sound and Rhythm\", which literary concept matches this definition: Punctuation or syntactic completion gives a line a definite pause?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"End-stop"},{"id":"C","text":"Assonance"},{"id":"D","text":"Repetition"}],"answer":"B","explanation":"End-stop is the correct concept because Punctuation or syntactic completion gives a line a definite pause. The model example is: The first line ends with a full stop after shore. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Poetic Sound and Rhythm\": The first line ends with a full stop after shore?","options":[{"id":"A","text":"End-stop"},{"id":"B","text":"Alliteration"},{"id":"C","text":"Assonance"},{"id":"D","text":"Repetition"}],"answer":"A","explanation":"The example illustrates End-stop: Punctuation or syntactic completion gives a line a definite pause. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":2,"seq":1,"name":"Extended Prose and Chapter Design","slug":"lit-sss2-t2-extended-prose-and-chapter-design","code":"G26LITSSS2T2U1","body":"# Extended Prose and Chapter Design — SSS2 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nNovels ask readers to connect evidence across many scenes. Chapters can shift place, viewpoint or narrative pace. Ask what each chapter changes about the reader''s knowledge, not merely how many pages it contains.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Chapter One ends with a missing ledger. Chapter Two follows the apprentice carrying parcels on a rainy road. Chapter Three returns to the shop and reveals that the ledger was placed in the wrong cabinet before the storm.\n\n## A worked close reading\nThe chapter switch initially delays an answer and permits tension to accumulate. The eventual explanation revises suspicion without requiring a criminal act. A plot map should distinguish delay from permanent omission.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Chapter transition\n**Meaning:** A break in a longer prose work changes emphasis time or focus.\n**In practice:** The action moves from the shop to a rainy road. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Narrative pace\n**Meaning:** The perceived speed of events and presentation.\n**In practice:** A journey is summarised quickly after a long shop conversation. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Delayed disclosure\n**Meaning:** The narrator postpones information the reader seeks.\n**In practice:** The ledger''s location is disclosed in Chapter Three. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Parallel plot\n**Meaning:** Two strands of action unfold and may later connect.\n**In practice:** The apprentice travels while the shopkeeper searches. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Cohesion\n**Meaning:** Recurring details create continuity across separate episodes.\n**In practice:** The ledger links the shop and later discovery. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Chapter transition: A break in a longer prose work changes emphasis time or focus","Narrative pace: The perceived speed of events and presentation","Delayed disclosure: The narrator postpones information the reader seeks","Parallel plot: Two strands of action unfold and may later connect","Cohesion: Recurring details create continuity across separate episodes"],"cards":[{"front":"What does \"Chapter transition\" mean in literary study?","back":"A break in a longer prose work changes emphasis time or focus. Example: The action moves from the shop to a rainy road.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Narrative pace\" mean in literary study?","back":"The perceived speed of events and presentation. Example: A journey is summarised quickly after a long shop conversation.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Delayed disclosure\" mean in literary study?","back":"The narrator postpones information the reader seeks. Example: The ledger''s location is disclosed in Chapter Three.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Parallel plot\" mean in literary study?","back":"Two strands of action unfold and may later connect. Example: The apprentice travels while the shopkeeper searches.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Cohesion\" mean in literary study?","back":"Recurring details create continuity across separate episodes. Example: The ledger links the shop and later discovery.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate extended prose and chapter design?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Extended Prose and Chapter Design\", which literary concept matches this definition: A break in a longer prose work changes emphasis time or focus?","options":[{"id":"A","text":"Narrative pace"},{"id":"B","text":"Delayed disclosure"},{"id":"C","text":"Parallel plot"},{"id":"D","text":"Chapter transition"}],"answer":"D","explanation":"Chapter transition is the correct concept because A break in a longer prose work changes emphasis time or focus. The model example is: The action moves from the shop to a rainy road. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Extended Prose and Chapter Design\": The action moves from the shop to a rainy road?","options":[{"id":"A","text":"Narrative pace"},{"id":"B","text":"Delayed disclosure"},{"id":"C","text":"Chapter transition"},{"id":"D","text":"Parallel plot"}],"answer":"C","explanation":"The example illustrates Chapter transition: A break in a longer prose work changes emphasis time or focus. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Extended Prose and Chapter Design\", which literary concept matches this definition: The perceived speed of events and presentation?","options":[{"id":"A","text":"Chapter transition"},{"id":"B","text":"Narrative pace"},{"id":"C","text":"Delayed disclosure"},{"id":"D","text":"Parallel plot"}],"answer":"B","explanation":"Narrative pace is the correct concept because The perceived speed of events and presentation. The model example is: A journey is summarised quickly after a long shop conversation. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Extended Prose and Chapter Design\": A journey is summarised quickly after a long shop conversation?","options":[{"id":"A","text":"Narrative pace"},{"id":"B","text":"Chapter transition"},{"id":"C","text":"Delayed disclosure"},{"id":"D","text":"Parallel plot"}],"answer":"A","explanation":"The example illustrates Narrative pace: The perceived speed of events and presentation. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Extended Prose and Chapter Design\", which literary concept matches this definition: The narrator postpones information the reader seeks?","options":[{"id":"A","text":"Chapter transition"},{"id":"B","text":"Narrative pace"},{"id":"C","text":"Parallel plot"},{"id":"D","text":"Delayed disclosure"}],"answer":"D","explanation":"Delayed disclosure is the correct concept because The narrator postpones information the reader seeks. The model example is: The ledger''s location is disclosed in Chapter Three. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Extended Prose and Chapter Design\": The ledger''s location is disclosed in Chapter Three?","options":[{"id":"A","text":"Chapter transition"},{"id":"B","text":"Narrative pace"},{"id":"C","text":"Delayed disclosure"},{"id":"D","text":"Parallel plot"}],"answer":"C","explanation":"The example illustrates Delayed disclosure: The narrator postpones information the reader seeks. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Extended Prose and Chapter Design\", which literary concept matches this definition: Two strands of action unfold and may later connect?","options":[{"id":"A","text":"Chapter transition"},{"id":"B","text":"Parallel plot"},{"id":"C","text":"Narrative pace"},{"id":"D","text":"Delayed disclosure"}],"answer":"B","explanation":"Parallel plot is the correct concept because Two strands of action unfold and may later connect. The model example is: The apprentice travels while the shopkeeper searches. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Extended Prose and Chapter Design\": The apprentice travels while the shopkeeper searches?","options":[{"id":"A","text":"Parallel plot"},{"id":"B","text":"Chapter transition"},{"id":"C","text":"Narrative pace"},{"id":"D","text":"Delayed disclosure"}],"answer":"A","explanation":"The example illustrates Parallel plot: Two strands of action unfold and may later connect. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Extended Prose and Chapter Design\", which literary concept matches this definition: Recurring details create continuity across separate episodes?","options":[{"id":"A","text":"Chapter transition"},{"id":"B","text":"Narrative pace"},{"id":"C","text":"Delayed disclosure"},{"id":"D","text":"Cohesion"}],"answer":"D","explanation":"Cohesion is the correct concept because Recurring details create continuity across separate episodes. The model example is: The ledger links the shop and later discovery. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Extended Prose and Chapter Design\": The ledger links the shop and later discovery?","options":[{"id":"A","text":"Chapter transition"},{"id":"B","text":"Narrative pace"},{"id":"C","text":"Cohesion"},{"id":"D","text":"Delayed disclosure"}],"answer":"C","explanation":"The example illustrates Cohesion: Recurring details create continuity across separate episodes. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":2,"seq":2,"name":"Character Networks and Social Power","slug":"lit-sss2-t2-character-networks-and-social-power","code":"G26LITSSS2T2U2","body":"# Character Networks and Social Power — SSS2 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nCharacters rarely act independently of family, institutions and unequal resources. Distinguish structural pressure from individual motive; a person may make a choice under constraints without becoming a simple representative of a group.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> At the factory gate, the supervisor told workers they could appeal the new shift rota. Only those with transport money could remain after closing to attend the meeting. Nkiru, who lived far away, wrote a letter instead. The next day the committee read her note aloud.\n\n## A worked close reading\nThe appeal procedure exists, but the meeting time excludes some workers. Nkiru''s letter demonstrates agency within a constraint. A simplistic answer that the supervisor is wholly benevolent or cruel ignores the mixed evidence.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Power relationship\n**Meaning:** An unequal ability to influence another person''s options.\n**In practice:** The supervisor determines the appeal meeting time. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Institutional barrier\n**Meaning:** A rule or practice limits fair participation.\n**In practice:** Only workers who can remain late can speak in person. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Agency\n**Meaning:** A person''s capacity to choose and act within circumstances.\n**In practice:** Nkiru sends a written appeal instead of attending. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Character network\n**Meaning:** Relationships reveal pressures and alliances in the story.\n**In practice:** Supervisor committee and workers influence one another. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Social critique\n**Meaning:** A narrative questions practices that produce unjust outcomes.\n**In practice:** The story exposes unequal access to the hearing. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Power relationship: An unequal ability to influence another person''s options","Institutional barrier: A rule or practice limits fair participation","Agency: A person''s capacity to choose and act within circumstances","Character network: Relationships reveal pressures and alliances in the story","Social critique: A narrative questions practices that produce unjust outcomes"],"cards":[{"front":"What does \"Power relationship\" mean in literary study?","back":"An unequal ability to influence another person''s options. Example: The supervisor determines the appeal meeting time.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Institutional barrier\" mean in literary study?","back":"A rule or practice limits fair participation. Example: Only workers who can remain late can speak in person.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Agency\" mean in literary study?","back":"A person''s capacity to choose and act within circumstances. Example: Nkiru sends a written appeal instead of attending.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Character network\" mean in literary study?","back":"Relationships reveal pressures and alliances in the story. Example: Supervisor committee and workers influence one another.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Social critique\" mean in literary study?","back":"A narrative questions practices that produce unjust outcomes. Example: The story exposes unequal access to the hearing.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate character networks and social power?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Character Networks and Social Power\", which literary concept matches this definition: An unequal ability to influence another person''s options?","options":[{"id":"A","text":"Institutional barrier"},{"id":"B","text":"Power relationship"},{"id":"C","text":"Agency"},{"id":"D","text":"Character network"}],"answer":"B","explanation":"Power relationship is the correct concept because An unequal ability to influence another person''s options. The model example is: The supervisor determines the appeal meeting time. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Networks and Social Power\": The supervisor determines the appeal meeting time?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Institutional barrier"},{"id":"C","text":"Agency"},{"id":"D","text":"Character network"}],"answer":"A","explanation":"The example illustrates Power relationship: An unequal ability to influence another person''s options. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Character Networks and Social Power\", which literary concept matches this definition: A rule or practice limits fair participation?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Agency"},{"id":"C","text":"Character network"},{"id":"D","text":"Institutional barrier"}],"answer":"D","explanation":"Institutional barrier is the correct concept because A rule or practice limits fair participation. The model example is: Only workers who can remain late can speak in person. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Networks and Social Power\": Only workers who can remain late can speak in person?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Agency"},{"id":"C","text":"Institutional barrier"},{"id":"D","text":"Character network"}],"answer":"C","explanation":"The example illustrates Institutional barrier: A rule or practice limits fair participation. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Character Networks and Social Power\", which literary concept matches this definition: A person''s capacity to choose and act within circumstances?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Agency"},{"id":"C","text":"Institutional barrier"},{"id":"D","text":"Character network"}],"answer":"B","explanation":"Agency is the correct concept because A person''s capacity to choose and act within circumstances. The model example is: Nkiru sends a written appeal instead of attending. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Networks and Social Power\": Nkiru sends a written appeal instead of attending?","options":[{"id":"A","text":"Agency"},{"id":"B","text":"Power relationship"},{"id":"C","text":"Institutional barrier"},{"id":"D","text":"Character network"}],"answer":"A","explanation":"The example illustrates Agency: A person''s capacity to choose and act within circumstances. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Character Networks and Social Power\", which literary concept matches this definition: Relationships reveal pressures and alliances in the story?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Institutional barrier"},{"id":"C","text":"Agency"},{"id":"D","text":"Character network"}],"answer":"D","explanation":"Character network is the correct concept because Relationships reveal pressures and alliances in the story. The model example is: Supervisor committee and workers influence one another. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Networks and Social Power\": Supervisor committee and workers influence one another?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Institutional barrier"},{"id":"C","text":"Character network"},{"id":"D","text":"Agency"}],"answer":"C","explanation":"The example illustrates Character network: Relationships reveal pressures and alliances in the story. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Character Networks and Social Power\", which literary concept matches this definition: A narrative questions practices that produce unjust outcomes?","options":[{"id":"A","text":"Power relationship"},{"id":"B","text":"Social critique"},{"id":"C","text":"Institutional barrier"},{"id":"D","text":"Agency"}],"answer":"B","explanation":"Social critique is the correct concept because A narrative questions practices that produce unjust outcomes. The model example is: The story exposes unequal access to the hearing. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Character Networks and Social Power\": The story exposes unequal access to the hearing?","options":[{"id":"A","text":"Social critique"},{"id":"B","text":"Power relationship"},{"id":"C","text":"Institutional barrier"},{"id":"D","text":"Agency"}],"answer":"A","explanation":"The example illustrates Social critique: A narrative questions practices that produce unjust outcomes. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":2,"seq":3,"name":"Nonlinear Narratives and Memory","slug":"lit-sss2-t2-nonlinear-narratives-and-memory","code":"G26LITSSS2T2U3","body":"# Nonlinear Narratives and Memory — SSS2 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nNonlinear stories do not reveal events in simple chronological order. A flashback supplies earlier information, a flashforward anticipates later events, and a frame narrative embeds one story inside another.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> At the reunion, Bisi sees an old classroom photograph. The narration returns to the day the picture was taken, when the class was divided over a missing prize. Back in the present, Bisi notices the certificate lying behind the frame.\n\n## A worked close reading\nThe memory sequence explains relationships and changes how the photo is read. The discovery occurs in the present; the recollection is not proof that Bisi solved the mystery years ago.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Nonlinear structure\n**Meaning:** Events are narrated out of chronological order.\n**In practice:** The reunion begins before the schoolday memory. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Flashback\n**Meaning:** Narration shifts to an earlier moment.\n**In practice:** The story revisits the day the photograph was taken. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Flashforward\n**Meaning:** Narration briefly anticipates later events.\n**In practice:** The narrator says this meeting will matter ten years later. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Frame narrative\n**Meaning:** An outer storytelling situation contains another story.\n**In practice:** Bisi tells her classmates a story inside the reunion scene. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Memory filter\n**Meaning:** Recollection may select or distort earlier details.\n**In practice:** Bisi recalls the missing prize but not who found it. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Nonlinear structure: Events are narrated out of chronological order","Flashback: Narration shifts to an earlier moment","Flashforward: Narration briefly anticipates later events","Frame narrative: An outer storytelling situation contains another story","Memory filter: Recollection may select or distort earlier details"],"cards":[{"front":"What does \"Nonlinear structure\" mean in literary study?","back":"Events are narrated out of chronological order. Example: The reunion begins before the schoolday memory.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Flashback\" mean in literary study?","back":"Narration shifts to an earlier moment. Example: The story revisits the day the photograph was taken.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Flashforward\" mean in literary study?","back":"Narration briefly anticipates later events. Example: The narrator says this meeting will matter ten years later.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Frame narrative\" mean in literary study?","back":"An outer storytelling situation contains another story. Example: Bisi tells her classmates a story inside the reunion scene.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Memory filter\" mean in literary study?","back":"Recollection may select or distort earlier details. Example: Bisi recalls the missing prize but not who found it.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate nonlinear narratives and memory?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Nonlinear Narratives and Memory\", which literary concept matches this definition: Events are narrated out of chronological order?","options":[{"id":"A","text":"Flashback"},{"id":"B","text":"Flashforward"},{"id":"C","text":"Frame narrative"},{"id":"D","text":"Nonlinear structure"}],"answer":"D","explanation":"Nonlinear structure is the correct concept because Events are narrated out of chronological order. The model example is: The reunion begins before the schoolday memory. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Nonlinear Narratives and Memory\": The reunion begins before the schoolday memory?","options":[{"id":"A","text":"Flashback"},{"id":"B","text":"Flashforward"},{"id":"C","text":"Nonlinear structure"},{"id":"D","text":"Frame narrative"}],"answer":"C","explanation":"The example illustrates Nonlinear structure: Events are narrated out of chronological order. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Nonlinear Narratives and Memory\", which literary concept matches this definition: Narration shifts to an earlier moment?","options":[{"id":"A","text":"Nonlinear structure"},{"id":"B","text":"Flashback"},{"id":"C","text":"Flashforward"},{"id":"D","text":"Frame narrative"}],"answer":"B","explanation":"Flashback is the correct concept because Narration shifts to an earlier moment. The model example is: The story revisits the day the photograph was taken. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Nonlinear Narratives and Memory\": The story revisits the day the photograph was taken?","options":[{"id":"A","text":"Flashback"},{"id":"B","text":"Nonlinear structure"},{"id":"C","text":"Flashforward"},{"id":"D","text":"Frame narrative"}],"answer":"A","explanation":"The example illustrates Flashback: Narration shifts to an earlier moment. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Nonlinear Narratives and Memory\", which literary concept matches this definition: Narration briefly anticipates later events?","options":[{"id":"A","text":"Nonlinear structure"},{"id":"B","text":"Flashback"},{"id":"C","text":"Frame narrative"},{"id":"D","text":"Flashforward"}],"answer":"D","explanation":"Flashforward is the correct concept because Narration briefly anticipates later events. The model example is: The narrator says this meeting will matter ten years later. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Nonlinear Narratives and Memory\": The narrator says this meeting will matter ten years later?","options":[{"id":"A","text":"Nonlinear structure"},{"id":"B","text":"Flashback"},{"id":"C","text":"Flashforward"},{"id":"D","text":"Frame narrative"}],"answer":"C","explanation":"The example illustrates Flashforward: Narration briefly anticipates later events. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Nonlinear Narratives and Memory\", which literary concept matches this definition: An outer storytelling situation contains another story?","options":[{"id":"A","text":"Nonlinear structure"},{"id":"B","text":"Frame narrative"},{"id":"C","text":"Flashback"},{"id":"D","text":"Flashforward"}],"answer":"B","explanation":"Frame narrative is the correct concept because An outer storytelling situation contains another story. The model example is: Bisi tells her classmates a story inside the reunion scene. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Nonlinear Narratives and Memory\": Bisi tells her classmates a story inside the reunion scene?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Nonlinear structure"},{"id":"C","text":"Flashback"},{"id":"D","text":"Flashforward"}],"answer":"A","explanation":"The example illustrates Frame narrative: An outer storytelling situation contains another story. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Nonlinear Narratives and Memory\", which literary concept matches this definition: Recollection may select or distort earlier details?","options":[{"id":"A","text":"Nonlinear structure"},{"id":"B","text":"Flashback"},{"id":"C","text":"Flashforward"},{"id":"D","text":"Memory filter"}],"answer":"D","explanation":"Memory filter is the correct concept because Recollection may select or distort earlier details. The model example is: Bisi recalls the missing prize but not who found it. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Nonlinear Narratives and Memory\": Bisi recalls the missing prize but not who found it?","options":[{"id":"A","text":"Nonlinear structure"},{"id":"B","text":"Flashback"},{"id":"C","text":"Memory filter"},{"id":"D","text":"Flashforward"}],"answer":"C","explanation":"The example illustrates Memory filter: Recollection may select or distort earlier details. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":2,"seq":4,"name":"Thematic Essays and Counterargument","slug":"lit-sss2-t2-thematic-essays-and-counterargument","code":"G26LITSSS2T2U4","body":"# Thematic Essays and Counterargument — SSS2 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nA higher-level Literature essay should develop a specific thesis and acknowledge reasonable limits. Differentiate describing an issue from proving how a text examines that issue. Use the prompt''s wording to organise a purposeful response.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> Original extract: ''Tunde could not repair the broken bridge himself. He wrote to the council, then called the farmers together. When the materials finally arrived, everyone carried a plank, though the river was still rising.''\n\n## A worked close reading\nThe scene supports a theme about cooperation amid limited individual power. It does not prove that official institutions solved the problem alone; farmers and council appear to contribute. An alternative reading might examine the council''s delay.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Thesis\n**Meaning:** A specific arguable answer guiding the whole essay.\n**In practice:** The passage presents cooperation as necessary under pressure. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Topic sentence\n**Meaning:** A paragraph opening advances one part of the thesis.\n**In practice:** The broken bridge first reveals limits of individual action. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Embedded evidence\n**Meaning:** A brief textual detail is integrated into analysis.\n**In practice:** Everyone carried a plank supplies evidence of collective effort. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Counterargument\n**Meaning:** Another plausible reading is considered and tested.\n**In practice:** The council''s delayed response may also reveal institutional weakness. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Synthesis\n**Meaning:** A conclusion connects separate observations into a coherent judgement.\n**In practice:** Private initiative and public materials jointly enable the repair. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Thesis: A specific arguable answer guiding the whole essay","Topic sentence: A paragraph opening advances one part of the thesis","Embedded evidence: A brief textual detail is integrated into analysis","Counterargument: Another plausible reading is considered and tested","Synthesis: A conclusion connects separate observations into a coherent judgement"],"cards":[{"front":"What does \"Thesis\" mean in literary study?","back":"A specific arguable answer guiding the whole essay. Example: The passage presents cooperation as necessary under pressure.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Topic sentence\" mean in literary study?","back":"A paragraph opening advances one part of the thesis. Example: The broken bridge first reveals limits of individual action.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Embedded evidence\" mean in literary study?","back":"A brief textual detail is integrated into analysis. Example: Everyone carried a plank supplies evidence of collective effort.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Counterargument\" mean in literary study?","back":"Another plausible reading is considered and tested. Example: The council''s delayed response may also reveal institutional weakness.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Synthesis\" mean in literary study?","back":"A conclusion connects separate observations into a coherent judgement. Example: Private initiative and public materials jointly enable the repair.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate thematic essays and counterargument?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Thematic Essays and Counterargument\", which literary concept matches this definition: A specific arguable answer guiding the whole essay?","options":[{"id":"A","text":"Topic sentence"},{"id":"B","text":"Thesis"},{"id":"C","text":"Embedded evidence"},{"id":"D","text":"Counterargument"}],"answer":"B","explanation":"Thesis is the correct concept because A specific arguable answer guiding the whole essay. The model example is: The passage presents cooperation as necessary under pressure. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Thematic Essays and Counterargument\": The passage presents cooperation as necessary under pressure?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Topic sentence"},{"id":"C","text":"Embedded evidence"},{"id":"D","text":"Counterargument"}],"answer":"A","explanation":"The example illustrates Thesis: A specific arguable answer guiding the whole essay. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Thematic Essays and Counterargument\", which literary concept matches this definition: A paragraph opening advances one part of the thesis?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Embedded evidence"},{"id":"C","text":"Counterargument"},{"id":"D","text":"Topic sentence"}],"answer":"D","explanation":"Topic sentence is the correct concept because A paragraph opening advances one part of the thesis. The model example is: The broken bridge first reveals limits of individual action. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Thematic Essays and Counterargument\": The broken bridge first reveals limits of individual action?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Embedded evidence"},{"id":"C","text":"Topic sentence"},{"id":"D","text":"Counterargument"}],"answer":"C","explanation":"The example illustrates Topic sentence: A paragraph opening advances one part of the thesis. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Thematic Essays and Counterargument\", which literary concept matches this definition: A brief textual detail is integrated into analysis?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Embedded evidence"},{"id":"C","text":"Topic sentence"},{"id":"D","text":"Counterargument"}],"answer":"B","explanation":"Embedded evidence is the correct concept because A brief textual detail is integrated into analysis. The model example is: Everyone carried a plank supplies evidence of collective effort. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Thematic Essays and Counterargument\": Everyone carried a plank supplies evidence of collective effort?","options":[{"id":"A","text":"Embedded evidence"},{"id":"B","text":"Thesis"},{"id":"C","text":"Topic sentence"},{"id":"D","text":"Counterargument"}],"answer":"A","explanation":"The example illustrates Embedded evidence: A brief textual detail is integrated into analysis. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Thematic Essays and Counterargument\", which literary concept matches this definition: Another plausible reading is considered and tested?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Topic sentence"},{"id":"C","text":"Embedded evidence"},{"id":"D","text":"Counterargument"}],"answer":"D","explanation":"Counterargument is the correct concept because Another plausible reading is considered and tested. The model example is: The council''s delayed response may also reveal institutional weakness. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Thematic Essays and Counterargument\": The council''s delayed response may also reveal institutional weakness?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Topic sentence"},{"id":"C","text":"Counterargument"},{"id":"D","text":"Embedded evidence"}],"answer":"C","explanation":"The example illustrates Counterargument: Another plausible reading is considered and tested. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Thematic Essays and Counterargument\", which literary concept matches this definition: A conclusion connects separate observations into a coherent judgement?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Synthesis"},{"id":"C","text":"Topic sentence"},{"id":"D","text":"Embedded evidence"}],"answer":"B","explanation":"Synthesis is the correct concept because A conclusion connects separate observations into a coherent judgement. The model example is: Private initiative and public materials jointly enable the repair. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Thematic Essays and Counterargument\": Private initiative and public materials jointly enable the repair?","options":[{"id":"A","text":"Synthesis"},{"id":"B","text":"Thesis"},{"id":"C","text":"Topic sentence"},{"id":"D","text":"Embedded evidence"}],"answer":"A","explanation":"The example illustrates Synthesis: A conclusion connects separate observations into a coherent judgement. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]},{"level":"SSS2","term":2,"seq":5,"name":"Irony and Unreliable Prose Voices","slug":"lit-sss2-t2-irony-and-unreliable-prose-voices","code":"G26LITSSS2T2U5","body":"# Irony and Unreliable Prose Voices — SSS2 Literature in English, Second Term\n\n## Learning goals\nExplain the central literary concepts accurately; analyse an original passage using specific language as evidence; distinguish a plausible interpretation from an unsupported claim; apply these methods to an unseen piece of prose, poetry, or drama.\n\n## Why this unit matters\nIrony depends on contrast between expectation, statement and contextual knowledge. Narrators can omit facts, misinterpret motives or exaggerate. An unsupported assertion by a character is not a fact simply because it appears in dialogue.\n\nThis unit is a **skills-based teaching companion**, not a substitute for the prescribed literary text currently selected by a school or examination board. The original extracts here are written for practice; no passage is presented as a quotation from an assigned author or as a past examination question.\n\n## Original model passage\n> The village spokesman announced, ''All roads are open.'' Behind him, carts waited beside a collapsed culvert. He repeated the announcement as the first trader turned her cart around. Later the narrator adds that the spokesman had not travelled beyond the square.\n\n## A worked close reading\nThe spoken claim conflicts with visible obstacles. The narrator''s later explanation suggests limited knowledge rather than necessarily deliberate lying. State the contrast, then evaluate what is and is not known about intention.\n\nFirst establish what the passage *actually states*. Then explain the relevant word or action, its likely implication and what remains uncertain. A sound explanation can acknowledge more than one possibility, but it must point to evidence.\n\n## Five concepts to master\n### 1. Verbal irony\n**Meaning:** A speaker''s intended meaning contrasts with literal wording in context.\n**In practice:** Wonderful timing is said after a missed ferry. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 2. Situational irony\n**Meaning:** An outcome conflicts with reasonable expectations.\n**In practice:** The road opening ceremony occurs beside a collapsed bridge. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 3. Dramatic irony\n**Meaning:** The audience has important knowledge another character lacks.\n**In practice:** Traders see the blocked road before the spokesman does. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 4. Unreliable narrator\n**Meaning:** The account should be questioned because of limited or distorted knowledge.\n**In practice:** The speaker claims every road is open without checking routes. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n### 5. Qualification\n**Meaning:** Careful phrasing distinguishes firm evidence from inference.\n**In practice:** The spokesman may be mistaken rather than deliberately deceitful. The example is a clue to examine, not a shortcut that replaces an explanation. When using this term in an essay, identify one precise passage detail and connect it explicitly to the idea.\n\n## Guided practice: claim → detail → reasoning\nWrite a two-sentence claim about the original passage. In sentence one, state what the writer suggests. In sentence two, refer to a short, exact phrase or action and explain how it creates that suggestion. A response with only a label is incomplete; a response with only plot summary is not analysis.\n\nThen attempt a counter-reading: what different interpretation could a careful reader offer? Give one reason for accepting or limiting it. The point is not to invent a hidden story, but to reason within the evidence available.\n\n## Independent learner task\n1. Choose two concepts from the five above and locate the clearest illustration of each in the model passage or a new text.\n2. Explain how one word, action or stage choice affects the reader or audience.\n3. State one point the passage does **not** establish, and explain why it would be unsafe to claim certainty.\n4. Write a short analytical paragraph with a claim, evidence, explanation and balanced conclusion.\n5. Read the paragraph aloud and remove every sentence that merely repeats the storyline without developing the claim.\n\n## Assessment and marking guide\nA strong 10-mark response: **2 marks** for a clear interpretation, **2** for accurate literary terminology, **3** for specific evidence and insightful explanation, **2** for a meaningful qualification or alternative, and **1** for organisation and clear expression. Different justified interpretations may earn full credit.\n\n## Avoid these mistakes\nDo not confuse the speaker with the historical author; do not treat a character''s claim as a verified fact; do not name a device without discussing its effect; and do not label original practice material as an official paper. The attached questions include answers and explanations intended for revision and correction.","objectives":["Apply the named literary concept to an original text","Build evidence-based commentary and challenge unsupported inferences","Answer concept and application questions with explanations"],"points":["Verbal irony: A speaker''s intended meaning contrasts with literal wording in context","Situational irony: An outcome conflicts with reasonable expectations","Dramatic irony: The audience has important knowledge another character lacks","Unreliable narrator: The account should be questioned because of limited or distorted knowledge","Qualification: Careful phrasing distinguishes firm evidence from inference"],"cards":[{"front":"What does \"Verbal irony\" mean in literary study?","back":"A speaker''s intended meaning contrasts with literal wording in context. Example: Wonderful timing is said after a missed ferry.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Situational irony\" mean in literary study?","back":"An outcome conflicts with reasonable expectations. Example: The road opening ceremony occurs beside a collapsed bridge.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Dramatic irony\" mean in literary study?","back":"The audience has important knowledge another character lacks. Example: Traders see the blocked road before the spokesman does.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Unreliable narrator\" mean in literary study?","back":"The account should be questioned because of limited or distorted knowledge. Example: The speaker claims every road is open without checking routes.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"What does \"Qualification\" mean in literary study?","back":"Careful phrasing distinguishes firm evidence from inference. Example: The spokesman may be mistaken rather than deliberately deceitful.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How should you evaluate irony and unreliable prose voices?","back":"Make a claim, cite an exact detail, explain its effect, and distinguish what is supported from what is uncertain.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In the SSS2 lesson \"Irony and Unreliable Prose Voices\", which literary concept matches this definition: A speaker''s intended meaning contrasts with literal wording in context?","options":[{"id":"A","text":"Situational irony"},{"id":"B","text":"Dramatic irony"},{"id":"C","text":"Unreliable narrator"},{"id":"D","text":"Verbal irony"}],"answer":"D","explanation":"Verbal irony is the correct concept because A speaker''s intended meaning contrasts with literal wording in context. The model example is: Wonderful timing is said after a missed ferry. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Irony and Unreliable Prose Voices\": Wonderful timing is said after a missed ferry?","options":[{"id":"A","text":"Situational irony"},{"id":"B","text":"Dramatic irony"},{"id":"C","text":"Verbal irony"},{"id":"D","text":"Unreliable narrator"}],"answer":"C","explanation":"The example illustrates Verbal irony: A speaker''s intended meaning contrasts with literal wording in context. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Irony and Unreliable Prose Voices\", which literary concept matches this definition: An outcome conflicts with reasonable expectations?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Unreliable narrator"}],"answer":"B","explanation":"Situational irony is the correct concept because An outcome conflicts with reasonable expectations. The model example is: The road opening ceremony occurs beside a collapsed bridge. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Irony and Unreliable Prose Voices\": The road opening ceremony occurs beside a collapsed bridge?","options":[{"id":"A","text":"Situational irony"},{"id":"B","text":"Verbal irony"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Unreliable narrator"}],"answer":"A","explanation":"The example illustrates Situational irony: An outcome conflicts with reasonable expectations. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Irony and Unreliable Prose Voices\", which literary concept matches this definition: The audience has important knowledge another character lacks?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Unreliable narrator"},{"id":"D","text":"Dramatic irony"}],"answer":"D","explanation":"Dramatic irony is the correct concept because The audience has important knowledge another character lacks. The model example is: Traders see the blocked road before the spokesman does. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Irony and Unreliable Prose Voices\": Traders see the blocked road before the spokesman does?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Unreliable narrator"}],"answer":"C","explanation":"The example illustrates Dramatic irony: The audience has important knowledge another character lacks. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Irony and Unreliable Prose Voices\", which literary concept matches this definition: The account should be questioned because of limited or distorted knowledge?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Unreliable narrator"},{"id":"C","text":"Situational irony"},{"id":"D","text":"Dramatic irony"}],"answer":"B","explanation":"Unreliable narrator is the correct concept because The account should be questioned because of limited or distorted knowledge. The model example is: The speaker claims every road is open without checking routes. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Irony and Unreliable Prose Voices\": The speaker claims every road is open without checking routes?","options":[{"id":"A","text":"Unreliable narrator"},{"id":"B","text":"Verbal irony"},{"id":"C","text":"Situational irony"},{"id":"D","text":"Dramatic irony"}],"answer":"A","explanation":"The example illustrates Unreliable narrator: The account should be questioned because of limited or distorted knowledge. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"},{"question":"In the SSS2 lesson \"Irony and Unreliable Prose Voices\", which literary concept matches this definition: Careful phrasing distinguishes firm evidence from inference?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Qualification"}],"answer":"D","explanation":"Qualification is the correct concept because Careful phrasing distinguishes firm evidence from inference. The model example is: The spokesman may be mistaken rather than deliberately deceitful. This is original concept-based practice.","difficulty":"medium"},{"question":"Which concept best explains this specific example from \"Irony and Unreliable Prose Voices\": The spokesman may be mistaken rather than deliberately deceitful?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Qualification"},{"id":"D","text":"Dramatic irony"}],"answer":"C","explanation":"The example illustrates Qualification: Careful phrasing distinguishes firm evidence from inference. Look for the textual detail that makes this interpretation defensible rather than selecting a label without evidence.","difficulty":"medium"}]}]'::jsonb) AS x(level text,term int,seq int,name text,slug text,code text,body text,objectives jsonb,points jsonb,cards jsonb,questions jsonb);
CREATE TEMP TABLE literature_cohorts ON COMMIT DROP AS
SELECT cl.id class_id,cl.name class_name,cl.code class_code,
tm.id term_id,tm.name term_name,
u.level,u.term,
lower(replace(cl.code,'-','-'))||'-lit-'||case u.term when 1 then 'first' when 2 then 'second' else 'third' end||'-term' course_slug
FROM (SELECT DISTINCT level,term FROM new_lit_units) u
JOIN public.classes cl ON cl.code IN (u.level||'-A',u.level||'-B')
JOIN public.terms tm ON tm.code='TERM-'||u.term::text;
DO $guard$ BEGIN
 IF (SELECT count(*) FROM literature_cohorts)<>8
 THEN RAISE EXCEPTION 'Expected eight class/term combinations; class map changed'; END IF;
 IF (SELECT count(*) FROM public.subjects WHERE id='1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc' AND name='Literature in English')<>1
 THEN RAISE EXCEPTION 'Literature subject ID changed'; END IF;
 IF (SELECT count(*) FROM new_lit_units)<>20 THEN RAISE EXCEPTION 'Incomplete literature module batch'; END IF;
END $guard$;
INSERT INTO public.courses(id,subject_id,class_id,term_id,title,slug,short_description,full_description,difficulty,status,is_free,price,lesson_count,total_duration_hours,published_at,created_at,updated_at)
SELECT gen_random_uuid(),'1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc',k.class_id,k.term_id,
'Literature in English - '||k.class_name||' - '||k.term_name,k.course_slug,
'Original close-reading and literary skills with worked examples and practice.',
'Concept-rich prose, poetry and drama lessons using original model passages, flashcards, explanations and guided analysis. Prescribed texts should be studied separately.',
'intermediate','published',true,0,0,4,now(),now(),now()
FROM literature_cohorts k
WHERE NOT EXISTS (SELECT 1 FROM public.courses c WHERE c.subject_id='1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc' AND c.class_id=k.class_id AND c.term_id=k.term_id)
ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.course_sections(id,course_id,title,description,order_index,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.id,k.term_name||' Lessons','Original reading and practice for '||k.class_name,1,true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
WHERE NOT EXISTS(SELECT 1 FROM public.course_sections cs WHERE cs.course_id=c.id);
INSERT INTO public.topics(id,subject_id,class_id,term_id,name,code,description,learning_objectives,order_index,estimated_hours,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,c.class_id,c.term_id,u.name,u.code,'Original Literature skills and practice: '||u.name,
u.objectives,u.seq,1,true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
WHERE NOT EXISTS(SELECT 1 FROM public.topics t WHERE t.subject_id=c.subject_id AND t.class_id=c.class_id AND t.term_id=c.term_id AND lower(btrim(t.name))=lower(btrim(u.name)))
ON CONFLICT(subject_id,class_id,term_id,code) DO NOTHING;
INSERT INTO public.lessons(id,course_id,section_id,topic_id,title,slug,description,learning_objectives,content_type,written_content,key_points,order_index,is_free,is_published,estimated_minutes,teaching_version,content_quality,created_at,updated_at)
SELECT gen_random_uuid(),c.id,(SELECT cs.id FROM public.course_sections cs WHERE cs.course_id=c.id AND cs.is_active ORDER BY cs.order_index LIMIT 1),
t.id,u.level||' Literature: '||u.name,u.slug,'Original detailed study module with worked close reading and formative practice.',
u.objectives,'text',u.body,u.points,u.seq,true,true,35,3,'ready',now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
JOIN public.topics t ON t.subject_id=c.subject_id AND t.class_id=c.class_id AND t.term_id=c.term_id AND lower(btrim(t.name))=lower(btrim(u.name))
WHERE NOT EXISTS(SELECT 1 FROM public.lessons l WHERE l.course_id=c.id AND (l.slug=u.slug OR l.topic_id=t.id OR regexp_replace(lower(l.title),'[^a-z0-9]+','','g')=regexp_replace(lower(u.level||' Literature: '||u.name),'[^a-z0-9]+','','g')))
ON CONFLICT(course_id,slug) DO NOTHING;
INSERT INTO public.flashcards(id,course_id,lesson_id,topic_id,subject_id,title,description,cards,mode,is_public,created_at,updated_at)
SELECT gen_random_uuid(),l.course_id,l.id,l.topic_id,c.subject_id,u.level||' Literature: '||u.name,'Evidence-based concept recall',
u.cards,'curriculum-prebuilt',true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
JOIN public.lessons l ON l.course_id=c.id AND l.slug=u.slug
WHERE NOT EXISTS(SELECT 1 FROM public.flashcards f WHERE f.lesson_id=l.id AND f.is_public AND f.created_by IS NULL AND f.mode='curriculum-prebuilt')
ON CONFLICT DO NOTHING;
INSERT INTO public.questions(id,subject_id,topic_id,class_id,question_type,question_text,options,correct_answer,explanation,difficulty,marks,source,exam_name,tags,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,l.topic_id,c.class_id,'mcq',q->>'question',q->'options',to_jsonb(q->>'answer'),q->>'explanation','medium',1,
'THE GUIDE Original Literature Practice','Literature Skills and Close Reading Practice',
jsonb_build_array('original-literature','2026-skill-expansion','lesson:'||l.id::text),true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
JOIN public.lessons l ON l.course_id=c.id AND l.slug=u.slug
CROSS JOIN LATERAL jsonb_array_elements(u.questions) q
WHERE jsonb_array_length(q->'options')=4
AND NOT EXISTS(SELECT 1 FROM public.questions q0 WHERE q0.topic_id=l.topic_id
AND regexp_replace(lower(btrim(q0.question_text)),'[^a-z0-9]+','','g')=regexp_replace(lower(btrim(q->>'question')),'[^a-z0-9]+','','g') AND q0.is_active);
UPDATE public.courses c SET lesson_count=(SELECT count(*) FROM public.lessons l WHERE l.course_id=c.id AND l.is_published=true),updated_at=now()
WHERE c.slug IN(SELECT course_slug FROM literature_cohorts);
COMMIT;